window.GAOKAO_PAPERS=window.GAOKAO_PAPERS||{};window.GAOKAO_PAPERS["2022-tianjin"]=[{"id":"2022-tianjin-q01","paperId":"2022-tianjin","number":1,"type":"single","score":5,"lessonIds":["1.3"],"difficulty":"基础","hint":"先从全集里划掉B的成员，得到B的补集，再留下它与A共有的数。","legacy":false,"legacyReason":"","searchText":"设全集 U=\\{-2,-1,0,1,2\\} ，集合 A=\\{0,1,2\\} ， B=\\{-1,2\\} ，则 A\\cap\\left(C_UB\\right)= （ ） \\{0,1\\} \\{0,1,2\\} \\{-1,1,2\\} \\{-1,0,1,2\\}","questionHtml":"设全集 <span class=\"gk-math\" data-tex=\"U=\\{-2,-1,0,1,2\\}\">U=\\{-2,-1,0,1,2\\}</span>，集合 <span class=\"gk-math\" data-tex=\"A=\\{0,1,2\\}\">A=\\{0,1,2\\}</span>，<span class=\"gk-math\" data-tex=\"B=\\{-1,2\\}\">B=\\{-1,2\\}</span>，则 <span class=\"gk-math\" data-tex=\"A\\cap\\left(C_UB\\right)=\">A\\cap\\left(C_UB\\right)=</span>（ ）","optionsHtml":["<span class=\"gk-math\" data-tex=\"\\{0,1\\}\">\\{0,1\\}</span>","<span class=\"gk-math\" data-tex=\"\\{0,1,2\\}\">\\{0,1,2\\}</span>","<span class=\"gk-math\" data-tex=\"\\{-1,1,2\\}\">\\{-1,1,2\\}</span>","<span class=\"gk-math\" data-tex=\"\\{-1,0,1,2\\}\">\\{-1,0,1,2\\}</span>"],"answerHtml":"A","answerKey":"A","solutionHtml":"由全集 <span class=\"gk-math\" data-tex=\"U\">U</span> 可得 <span class=\"gk-math\" data-tex=\"C_UB=\\{-2,0,1\\}\">C_UB=\\{-2,0,1\\}</span>，因此 <span class=\"gk-math\" data-tex=\"A\\cap(C_UB)=\\{0,1,2\\}\\cap\\{-2,0,1\\}=\\{0,1\\}\">A\\cap(C_UB)=\\{0,1,2\\}\\cap\\{-2,0,1\\}=\\{0,1\\}</span>，故选 A.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-tianjin-q02","paperId":"2022-tianjin","number":2,"type":"single","score":5,"lessonIds":["1.4"],"difficulty":"基础","hint":"先想整数乘2再加1还是不是整数；反方向可试试x=1/2。","legacy":false,"legacyReason":"","searchText":"“ x 为整数”是“ 2x+1 为整数”的（ ） 充分不必要条件 必要不充分条件 充要条件 既不充分也不必要条件","questionHtml":"“<span class=\"gk-math\" data-tex=\"x\">x</span> 为整数”是“<span class=\"gk-math\" data-tex=\"2x+1\">2x+1</span> 为整数”的（ ）","optionsHtml":["充分不必要条件","必要不充分条件","充要条件","既不充分也不必要条件"],"answerHtml":"A","answerKey":"A","solutionHtml":"若 <span class=\"gk-math\" data-tex=\"x\">x</span> 为整数，则 <span class=\"gk-math\" data-tex=\"2x+1\">2x+1</span> 是整数，所以“<span class=\"gk-math\" data-tex=\"x\">x</span> 为整数”是“<span class=\"gk-math\" data-tex=\"2x+1\">2x+1</span> 为整数”的充分条件. 反之，取 <span class=\"gk-math\" data-tex=\"x=\\dfrac12\">x=\\dfrac12</span>，则 <span class=\"gk-math\" data-tex=\"2x+1=2\">2x+1=2</span> 为整数，而 <span class=\"gk-math\" data-tex=\"x\">x</span> 不是整数，所以必要性不成立. 故选 A.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-tianjin-q03","paperId":"2022-tianjin","number":3,"type":"single","score":5,"lessonIds":["3.2","3.1"],"difficulty":"进阶","hint":"先判断图象是否关于原点对称，再把x=1和一个大于1的数代进去，排除不合适的图。","legacy":false,"legacyReason":"","searchText":"函数 y=\\dfrac{|x^2-1|}{x} 的图象大致为（ ） ","questionHtml":"函数 <span class=\"gk-math\" data-tex=\"y=\\dfrac{|x^2-1|}{x}\">y=\\dfrac{|x^2-1|}{x}</span> 的图象大致为（ ）","optionsHtml":["<figure class=\"gk-figure\"><button class=\"gk-zoom\" style=\"width:min(100%,426px)\" data-action=\"zoom-image\" data-label=\"高考题图\" data-src=\"./assets/gaokao/figures/2022/tianjin/q3_option_a.webp\" aria-label=\"放大高考题图\"><img src=\"./assets/gaokao/figures/2022/tianjin/q3_option_a.webp\" alt=\"高考题图，点击可放大\" width=\"410\" height=\"410\" style=\"aspect-ratio:410/410;width:100%\" loading=\"lazy\"></button></figure>","<figure class=\"gk-figure\"><button class=\"gk-zoom\" style=\"width:min(100%,446px)\" data-action=\"zoom-image\" data-label=\"高考题图\" data-src=\"./assets/gaokao/figures/2022/tianjin/q3_option_b.webp\" aria-label=\"放大高考题图\"><img src=\"./assets/gaokao/figures/2022/tianjin/q3_option_b.webp\" alt=\"高考题图，点击可放大\" width=\"430\" height=\"410\" style=\"aspect-ratio:430/410;width:100%\" loading=\"lazy\"></button></figure>","<figure class=\"gk-figure\"><button class=\"gk-zoom\" style=\"width:min(100%,426px)\" data-action=\"zoom-image\" data-label=\"高考题图\" data-src=\"./assets/gaokao/figures/2022/tianjin/q3_option_c.webp\" aria-label=\"放大高考题图\"><img src=\"./assets/gaokao/figures/2022/tianjin/q3_option_c.webp\" alt=\"高考题图，点击可放大\" width=\"410\" height=\"396\" style=\"aspect-ratio:410/396;width:100%\" loading=\"lazy\"></button></figure>","<figure class=\"gk-figure\"><button class=\"gk-zoom\" style=\"width:min(100%,446px)\" data-action=\"zoom-image\" data-label=\"高考题图\" data-src=\"./assets/gaokao/figures/2022/tianjin/q3_option_d.webp\" aria-label=\"放大高考题图\"><img src=\"./assets/gaokao/figures/2022/tianjin/q3_option_d.webp\" alt=\"高考题图，点击可放大\" width=\"430\" height=\"430\" style=\"aspect-ratio:430/430;width:100%\" loading=\"lazy\"></button></figure>"],"answerHtml":"A","answerKey":"A","solutionHtml":"函数的定义域为 <span class=\"gk-math\" data-tex=\"x\\ne0\">x\\ne0</span>，且 <div class=\"gk-math display\" data-tex=\"y=\\begin{cases}\nx-\\dfrac{1}{x}, &amp; x\\le -1\\text{ 或 }x\\ge1,\\\\\n\\dfrac{1}{x}-x, &amp; -1&lt;x&lt;0\\text{ 或 }0&lt;x&lt;1.\n\\end{cases}\">y=\\begin{cases}\nx-\\dfrac{1}{x}, &amp; x\\le -1\\text{ 或 }x\\ge1,\\\\\n\\dfrac{1}{x}-x, &amp; -1&lt;x&lt;0\\text{ 或 }0&lt;x&lt;1.\n\\end{cases}</div> 当 <span class=\"gk-math\" data-tex=\"x&gt;0\">x&gt;0</span> 时，函数值为正；当 <span class=\"gk-math\" data-tex=\"x&lt;0\">x&lt;0</span> 时，函数值为负，且 <span class=\"gk-math\" data-tex=\"f(-x)=-f(x)\">f(-x)=-f(x)</span>. 又因为 <span class=\"gk-math\" data-tex=\"f(1)=0\">f(1)=0</span>，当 <span class=\"gk-math\" data-tex=\"0&lt;x&lt;1\">0&lt;x&lt;1</span> 时函数从正无穷递减到 <span class=\"gk-math\" data-tex=\"0\">0</span>，当 <span class=\"gk-math\" data-tex=\"x&gt;1\">x&gt;1</span> 时函数从 <span class=\"gk-math\" data-tex=\"0\">0</span> 递增. 因此图象应为选项 A，故选 A.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-tianjin-q04","paperId":"2022-tianjin","number":4,"type":"single","score":5,"lessonIds":["9.2"],"difficulty":"基础","hint":"直方图每根柱子的面积才是频率。最后两组的高度相加，再乘组距0.2和总数100。","legacy":false,"legacyReason":"","searchText":"将 1916 年到 2015 年的全球年平均气温（单位： {}^{\\circ}\\mathrm C ），共 100 个数据，分成 6 组： [13.55,13.75) ， [13.75,13.95) ， [13.95,14.15) ， [14.15,14.35) ， [14.35,14.55) ， [14.55,14.75] ，并整理得到如下的频率分布直方图，则全球年平均气温在区间 [14.35,14.75] 内的有（ ） 22\\text{ 年} 23\\text{ 年} 25\\text{ 年} 35\\text{ 年}","questionHtml":"将 1916 年到 2015 年的全球年平均气温（单位：<span class=\"gk-math\" data-tex=\"{}^{\\circ}\\mathrm C\">{}^{\\circ}\\mathrm C</span>），共 100 个数据，分成 6 组：<span class=\"gk-math\" data-tex=\"[13.55,13.75)\">[13.55,13.75)</span>，<span class=\"gk-math\" data-tex=\"[13.75,13.95)\">[13.75,13.95)</span>，<span class=\"gk-math\" data-tex=\"[13.95,14.15)\">[13.95,14.15)</span>，<span class=\"gk-math\" data-tex=\"[14.15,14.35)\">[14.15,14.35)</span>，<span class=\"gk-math\" data-tex=\"[14.35,14.55)\">[14.35,14.55)</span>，<span class=\"gk-math\" data-tex=\"[14.55,14.75]\">[14.55,14.75]</span>，并整理得到如下的频率分布直方图，则全球年平均气温在区间 <span class=\"gk-math\" data-tex=\"[14.35,14.75]\">[14.35,14.75]</span> 内的有（ ）<br><br><figure class=\"gk-figure\"><button class=\"gk-zoom\" style=\"width:min(100%,1213px)\" data-action=\"zoom-image\" data-label=\"高考题图\" data-src=\"./assets/gaokao/figures/2022/tianjin/q4_fig1.webp\" aria-label=\"放大高考题图\"><img src=\"./assets/gaokao/figures/2022/tianjin/q4_fig1.webp\" alt=\"高考题图，点击可放大\" width=\"1197\" height=\"815\" style=\"aspect-ratio:1197/815;width:100%\" loading=\"lazy\"></button></figure>","optionsHtml":["<span class=\"gk-math\" data-tex=\"22\\text{ 年}\">22\\text{ 年}</span>","<span class=\"gk-math\" data-tex=\"23\\text{ 年}\">23\\text{ 年}</span>","<span class=\"gk-math\" data-tex=\"25\\text{ 年}\">25\\text{ 年}</span>","<span class=\"gk-math\" data-tex=\"35\\text{ 年}\">35\\text{ 年}</span>"],"answerHtml":"B","answerKey":"B","solutionHtml":"由直方图可读出各组的组距均为 <span class=\"gk-math\" data-tex=\"0.20\">0.20</span>，相应的频率分布直方图高度依次为 <span class=\"gk-math\" data-tex=\"0.40\">0.40</span>，<span class=\"gk-math\" data-tex=\"1.30\">1.30</span>，<span class=\"gk-math\" data-tex=\"1.55\">1.55</span>，<span class=\"gk-math\" data-tex=\"0.60\">0.60</span>，<span class=\"gk-math\" data-tex=\"0.50\">0.50</span>，<span class=\"gk-math\" data-tex=\"0.65\">0.65</span>.<br><br>区间 <span class=\"gk-math\" data-tex=\"[14.35,14.75]\">[14.35,14.75]</span> 对应第五、六组，其频率为 <span class=\"gk-math\" data-tex=\"0.20(0.50+0.65)=0.23\">0.20(0.50+0.65)=0.23</span>，故数据个数为 <span class=\"gk-math\" data-tex=\"100\\times0.23=23\">100\\times0.23=23</span>，选 B.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-tianjin-q05","paperId":"2022-tianjin","number":5,"type":"single","score":5,"lessonIds":["4.2","4.4"],"difficulty":"基础","hint":"用0和1作比较的标杆：a在1的哪边，b在0与1之间吗，c是正还是负？","legacy":false,"legacyReason":"","searchText":"设 a=2^{0.7} ， b=\\left(\\dfrac{1}{3}\\right)^{0.7} ， c=\\log_2\\dfrac{1}{3} ，则 a ， b ， c 的大小关系为（ ） a<b<c c<a<b b<c<a c<b<a","questionHtml":"设 <span class=\"gk-math\" data-tex=\"a=2^{0.7}\">a=2^{0.7}</span>，<span class=\"gk-math\" data-tex=\"b=\\left(\\dfrac{1}{3}\\right)^{0.7}\">b=\\left(\\dfrac{1}{3}\\right)^{0.7}</span>，<span class=\"gk-math\" data-tex=\"c=\\log_2\\dfrac{1}{3}\">c=\\log_2\\dfrac{1}{3}</span>，则 <span class=\"gk-math\" data-tex=\"a\">a</span>，<span class=\"gk-math\" data-tex=\"b\">b</span>，<span class=\"gk-math\" data-tex=\"c\">c</span> 的大小关系为（ ）","optionsHtml":["<span class=\"gk-math\" data-tex=\"a&lt;b&lt;c\">a&lt;b&lt;c</span>","<span class=\"gk-math\" data-tex=\"c&lt;a&lt;b\">c&lt;a&lt;b</span>","<span class=\"gk-math\" data-tex=\"b&lt;c&lt;a\">b&lt;c&lt;a</span>","<span class=\"gk-math\" data-tex=\"c&lt;b&lt;a\">c&lt;b&lt;a</span>"],"answerHtml":"D","answerKey":"D","solutionHtml":"因为 <span class=\"gk-math\" data-tex=\"a=2^{0.7}&gt;1\">a=2^{0.7}&gt;1</span>，<span class=\"gk-math\" data-tex=\"0&lt;b=\\left(\\dfrac{1}{3}\\right)^{0.7}&lt;1\">0&lt;b=\\left(\\dfrac{1}{3}\\right)^{0.7}&lt;1</span>，而 <span class=\"gk-math\" data-tex=\"c=\\log_2\\dfrac{1}{3}&lt;0\">c=\\log_2\\dfrac{1}{3}&lt;0</span>，所以 <span class=\"gk-math\" data-tex=\"c&lt;b&lt;a\">c&lt;b&lt;a</span>，故选 D.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-tianjin-q06","paperId":"2022-tianjin","number":6,"type":"single","score":5,"lessonIds":["4.3"],"difficulty":"进阶","hint":"先用换底公式，把所有对数都换成以2为底。可以把log₂3暂时记成t。","legacy":false,"legacyReason":"","searchText":"化简 \\left(2\\log_4 3+\\log_8 3\\right)\\left(\\log_3 2+\\log_9 2\\right)= （ ） 1 \\dfrac{5}{4} 2 \\dfrac{5}{2}","questionHtml":"化简 <span class=\"gk-math\" data-tex=\"\\left(2\\log_4 3+\\log_8 3\\right)\\left(\\log_3 2+\\log_9 2\\right)=\">\\left(2\\log_4 3+\\log_8 3\\right)\\left(\\log_3 2+\\log_9 2\\right)=</span>（ ）","optionsHtml":["1","<span class=\"gk-math\" data-tex=\"\\dfrac{5}{4}\">\\dfrac{5}{4}</span>","2","<span class=\"gk-math\" data-tex=\"\\dfrac{5}{2}\">\\dfrac{5}{2}</span>"],"answerHtml":"C","answerKey":"C","solutionHtml":"设 <span class=\"gk-math\" data-tex=\"t=\\log_2 3\">t=\\log_2 3</span>，则 <span class=\"gk-math\" data-tex=\"\\log_4 3=\\dfrac{t}{2}\">\\log_4 3=\\dfrac{t}{2}</span>，<span class=\"gk-math\" data-tex=\"\\log_8 3=\\dfrac{t}{3}\">\\log_8 3=\\dfrac{t}{3}</span>，<span class=\"gk-math\" data-tex=\"\\log_3 2=\\dfrac{1}{t}\">\\log_3 2=\\dfrac{1}{t}</span>，<span class=\"gk-math\" data-tex=\"\\log_9 2=\\dfrac{1}{2t}\">\\log_9 2=\\dfrac{1}{2t}</span>. 因此原式等于 <div class=\"gk-math display\" data-tex=\"\\left(t+\\dfrac{t}{3}\\right)\\left(\\dfrac{1}{t}+\\dfrac{1}{2t}\\right)=\\dfrac{4t}{3}\\cdot\\dfrac{3}{2t}=2\">\\left(t+\\dfrac{t}{3}\\right)\\left(\\dfrac{1}{t}+\\dfrac{1}{2t}\\right)=\\dfrac{4t}{3}\\cdot\\dfrac{3}{2t}=2</div> 故选 C.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-tianjin-q07","paperId":"2022-tianjin","number":7,"type":"single","score":5,"lessonIds":["e1-3.2","e1-3.3","e1-2.1"],"difficulty":"进阶","hint":"抛物线准线经过左焦点，先求出双曲线的c。再用45°写出交点A的横纵距离关系。","legacy":false,"legacyReason":"","searchText":"已知双曲线 \\dfrac{x^2}{a^2}-\\dfrac{y^2}{b^2}=1 （ a>0 ， b>1 ）的左，右焦点分别为 F_1 ， F_2 ，抛物线 y^2=4\\sqrt{5}x 的准线经过 F_1 ，且与双曲线的一条渐近线交于点 A . 若 \\angle F_1F_2A=\\dfrac{\\pi}{4} ，则双曲线的方程为（ ） \\dfrac{x^2}{16}-\\dfrac{y^2}{4}=1 \\dfrac{x^2}{4}-\\dfrac{y^2}{16}=1 \\dfrac{x^2}{4}-y^2=1 x^2-\\dfrac{y^2}{4}=1","questionHtml":"已知双曲线 <span class=\"gk-math\" data-tex=\"\\dfrac{x^2}{a^2}-\\dfrac{y^2}{b^2}=1\">\\dfrac{x^2}{a^2}-\\dfrac{y^2}{b^2}=1</span>（<span class=\"gk-math\" data-tex=\"a&gt;0\">a&gt;0</span>，<span class=\"gk-math\" data-tex=\"b&gt;1\">b&gt;1</span>）的左，右焦点分别为 <span class=\"gk-math\" data-tex=\"F_1\">F_1</span>，<span class=\"gk-math\" data-tex=\"F_2\">F_2</span>，抛物线 <span class=\"gk-math\" data-tex=\"y^2=4\\sqrt{5}x\">y^2=4\\sqrt{5}x</span> 的准线经过 <span class=\"gk-math\" data-tex=\"F_1\">F_1</span>，且与双曲线的一条渐近线交于点 <span class=\"gk-math\" data-tex=\"A\">A</span>. 若 <span class=\"gk-math\" data-tex=\"\\angle F_1F_2A=\\dfrac{\\pi}{4}\">\\angle F_1F_2A=\\dfrac{\\pi}{4}</span>，则双曲线的方程为（ ）","optionsHtml":["<span class=\"gk-math\" data-tex=\"\\dfrac{x^2}{16}-\\dfrac{y^2}{4}=1\">\\dfrac{x^2}{16}-\\dfrac{y^2}{4}=1</span>","<span class=\"gk-math\" data-tex=\"\\dfrac{x^2}{4}-\\dfrac{y^2}{16}=1\">\\dfrac{x^2}{4}-\\dfrac{y^2}{16}=1</span>","<span class=\"gk-math\" data-tex=\"\\dfrac{x^2}{4}-y^2=1\">\\dfrac{x^2}{4}-y^2=1</span>","<span class=\"gk-math\" data-tex=\"x^2-\\dfrac{y^2}{4}=1\">x^2-\\dfrac{y^2}{4}=1</span>"],"answerHtml":"D","answerKey":"D","solutionHtml":"设双曲线的半焦距为 <span class=\"gk-math\" data-tex=\"c\">c</span>. 抛物线的准线为 <span class=\"gk-math\" data-tex=\"x=-\\sqrt{5}\">x=-\\sqrt{5}</span>，故 <span class=\"gk-math\" data-tex=\"F_1=(-\\sqrt{5},0)\">F_1=(-\\sqrt{5},0)</span>，从而 <span class=\"gk-math\" data-tex=\"c=\\sqrt{5}\">c=\\sqrt{5}</span>，即 <span class=\"gk-math\" data-tex=\"a^2+b^2=5\">a^2+b^2=5</span>. 双曲线的渐近线为 <span class=\"gk-math\" data-tex=\"y=\\pm\\dfrac{b}{a}x\">y=\\pm\\dfrac{b}{a}x</span>，所以直线 <span class=\"gk-math\" data-tex=\"x=-\\sqrt{5}\">x=-\\sqrt{5}</span> 与渐近线的交点可取 <span class=\"gk-math\" data-tex=\"A=(-\\sqrt{5},\\pm\\dfrac{b\\sqrt{5}}{a})\">A=(-\\sqrt{5},\\pm\\dfrac{b\\sqrt{5}}{a})</span>.<br><br>此时 <span class=\"gk-math\" data-tex=\"F_2=(\\sqrt{5},0)\">F_2=(\\sqrt{5},0)</span>，故 <span class=\"gk-math\" data-tex=\"\\overrightarrow{F_2F_1}=(-2\\sqrt{5},0)\">\\overrightarrow{F_2F_1}=(-2\\sqrt{5},0)</span>，且 <span class=\"gk-math\" data-tex=\"\\overrightarrow{F_2A}=(-2\\sqrt{5},\\pm\\dfrac{b\\sqrt{5}}{a})\">\\overrightarrow{F_2A}=(-2\\sqrt{5},\\pm\\dfrac{b\\sqrt{5}}{a})</span>. 由夹角为 <span class=\"gk-math\" data-tex=\"\\dfrac{\\pi}{4}\">\\dfrac{\\pi}{4}</span>，得 <div class=\"gk-math display\" data-tex=\"\\tan\\angle F_1F_2A=\\dfrac{b\\frac{\\sqrt{5}}{a}}{2\\sqrt{5}}=\\dfrac{b}{2a}=1\">\\tan\\angle F_1F_2A=\\dfrac{b\\frac{\\sqrt{5}}{a}}{2\\sqrt{5}}=\\dfrac{b}{2a}=1</div> 所以 <span class=\"gk-math\" data-tex=\"b=2a\">b=2a</span>. 代入 <span class=\"gk-math\" data-tex=\"a^2+b^2=5\">a^2+b^2=5</span>，得 <span class=\"gk-math\" data-tex=\"5a^2=5\">5a^2=5</span>，即 <span class=\"gk-math\" data-tex=\"a=1\">a=1</span>，<span class=\"gk-math\" data-tex=\"b=2\">b=2</span>. 故双曲线方程为 <span class=\"gk-math\" data-tex=\"x^2-\\dfrac{y^2}{4}=1\">x^2-\\dfrac{y^2}{4}=1</span>，选 D.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-tianjin-q08","paperId":"2022-tianjin","number":8,"type":"single","score":5,"lessonIds":["8.3","6.4"],"difficulty":"进阶","hint":"先算等腰三角形BCE的底边和高。把两个棱柱重叠的部分单独找出来，体积不能直接相加。","legacy":false,"legacyReason":"","searchText":"“十字歇山顶”是中国古代建筑屋顶的经典样式之一，图 1 中的故宫角楼的顶部即为十字歇山顶. 其上部可视为由两个相同的直三棱柱交叠而成的几何体（图 2）. 这两个直三棱柱有一个公共侧面 ABCD ，在底面 BCE 中，若 BE=CE=3 ， \\angle BEC=120^{\\circ} ，则该几何体的体积为（ ） \\dfrac{27}{2} \\dfrac{27\\sqrt{3}}{2} 27 27\\sqrt{3}","questionHtml":"“十字歇山顶”是中国古代建筑屋顶的经典样式之一，图 1 中的故宫角楼的顶部即为十字歇山顶. 其上部可视为由两个相同的直三棱柱交叠而成的几何体（图 2）. 这两个直三棱柱有一个公共侧面 <span class=\"gk-math\" data-tex=\"ABCD\">ABCD</span>，在底面 <span class=\"gk-math\" data-tex=\"BCE\">BCE</span> 中，若 <span class=\"gk-math\" data-tex=\"BE=CE=3\">BE=CE=3</span>，<span class=\"gk-math\" data-tex=\"\\angle BEC=120^{\\circ}\">\\angle BEC=120^{\\circ}</span>，则该几何体的体积为（ ）<br><br><div class=\"gk-table-scroll\"><table class=\"gk-table\"><tr><td><figure class=\"gk-figure\"><button class=\"gk-zoom\" style=\"width:min(100%,467px)\" data-action=\"zoom-image\" data-label=\"高考题图\" data-src=\"./assets/gaokao/figures/2022/tianjin/q8_fig1.webp\" aria-label=\"放大高考题图\"><img src=\"./assets/gaokao/figures/2022/tianjin/q8_fig1.webp\" alt=\"高考题图，点击可放大\" width=\"451\" height=\"324\" style=\"aspect-ratio:451/324;width:100%\" loading=\"lazy\"></button></figure></td><td><figure class=\"gk-figure\"><button class=\"gk-zoom\" style=\"width:min(100%,449px)\" data-action=\"zoom-image\" data-label=\"高考题图\" data-src=\"./assets/gaokao/figures/2022/tianjin/q8_fig2.webp\" aria-label=\"放大高考题图\"><img src=\"./assets/gaokao/figures/2022/tianjin/q8_fig2.webp\" alt=\"高考题图，点击可放大\" width=\"433\" height=\"272\" style=\"aspect-ratio:433/272;width:100%\" loading=\"lazy\"></button></figure></td></tr></table></div>","optionsHtml":["<span class=\"gk-math\" data-tex=\"\\dfrac{27}{2}\">\\dfrac{27}{2}</span>","<span class=\"gk-math\" data-tex=\"\\dfrac{27\\sqrt{3}}{2}\">\\dfrac{27\\sqrt{3}}{2}</span>","27","<span class=\"gk-math\" data-tex=\"27\\sqrt{3}\">27\\sqrt{3}</span>"],"answerHtml":"C","answerKey":"C","solutionHtml":"记底面三角形 <span class=\"gk-math\" data-tex=\"BCE\">BCE</span> 的面积为 <span class=\"gk-math\" data-tex=\"S\">S</span>，则 <div class=\"gk-math display\" data-tex=\"S=\\frac12\\cdot BE\\cdot CE\\cdot\\sin\\angle BEC\n=\\frac12\\cdot3\\cdot3\\cdot\\sin120^\\circ\n=\\frac{9\\sqrt3}{4}\">S=\\frac12\\cdot BE\\cdot CE\\cdot\\sin\\angle BEC\n=\\frac12\\cdot3\\cdot3\\cdot\\sin120^\\circ\n=\\frac{9\\sqrt3}{4}</div> 由余弦定理， <div class=\"gk-math display\" data-tex=\"BC^2=BE^2-2BE\\cdot CE\\cos120^\\circ+CE^2\n=9+9+9=27\">BC^2=BE^2-2BE\\cdot CE\\cos120^\\circ+CE^2\n=9+9+9=27</div> 所以 <span class=\"gk-math\" data-tex=\"BC=3\\sqrt3\">BC=3\\sqrt3</span>.<br><br>由图中两个全等棱柱的对应关系，共同侧面 <span class=\"gk-math\" data-tex=\"ABCD\">ABCD</span> 的边 <span class=\"gk-math\" data-tex=\"BC\">BC</span> 在一个棱柱中是底面边，在另一个棱柱中是侧棱；同理，<span class=\"gk-math\" data-tex=\"CD\">CD</span> 在前一个棱柱中是侧棱，在后一个棱柱中是底面边. 因此 <span class=\"gk-math\" data-tex=\"CD=BC\">CD=BC</span>. 令 <span class=\"gk-math\" data-tex=\"h=BC=CD=3\\sqrt3\">h=BC=CD=3\\sqrt3</span>，则 <span class=\"gk-math\" data-tex=\"ABCD\">ABCD</span> 为边长 <span class=\"gk-math\" data-tex=\"h\">h</span> 的正方形. 建立空间直角坐标系，使 <span class=\"gk-math\" data-tex=\"B=(0,0,0)\">B=(0,0,0)</span>，<span class=\"gk-math\" data-tex=\"C=(h,0,0)\">C=(h,0,0)</span>，<span class=\"gk-math\" data-tex=\"A=(0,h,0)\">A=(0,h,0)</span>，<span class=\"gk-math\" data-tex=\"D=(h,h,0)\">D=(h,h,0)</span>. 由等腰三角形 <span class=\"gk-math\" data-tex=\"BCE\">BCE</span> 的对称性，取 <span class=\"gk-math\" data-tex=\"E=\\left(\\dfrac h2,0,\\dfrac{h}{2\\sqrt3}\\right)\">E=\\left(\\dfrac h2,0,\\dfrac{h}{2\\sqrt3}\\right)</span>. 设另一个棱柱底面中与 <span class=\"gk-math\" data-tex=\"E\">E</span> 对应的顶点为 <span class=\"gk-math\" data-tex=\"G\">G</span>，则可取 <span class=\"gk-math\" data-tex=\"G=\\left(0,\\dfrac h2,\\dfrac{h}{2\\sqrt3}\\right)\">G=\\left(0,\\dfrac h2,\\dfrac{h}{2\\sqrt3}\\right)</span>.<br><br>在 <span class=\"gk-math\" data-tex=\"0\\leq t\\leq h\">0\\leq t\\leq h</span> 上令 <span class=\"gk-math\" data-tex=\"\\varphi(t)=\\dfrac1{\\sqrt3}\\min\\{t,h-t\\}\">\\varphi(t)=\\dfrac1{\\sqrt3}\\min\\{t,h-t\\}</span>. 第一个棱柱在点 <span class=\"gk-math\" data-tex=\"(x,y,z)\">(x,y,z)</span> 上的范围为 <span class=\"gk-math\" data-tex=\"0\\leq z\\leq\\varphi(x)\">0\\leq z\\leq\\varphi(x)</span>，第二个棱柱的范围为 <span class=\"gk-math\" data-tex=\"0\\leq z\\leq\\varphi(y)\">0\\leq z\\leq\\varphi(y)</span>. 第一个棱柱的体积为 <span class=\"gk-math\" data-tex=\"Sh\">Sh</span>.<br><br>考虑第二个棱柱在第一个棱柱外的部分. 当 <span class=\"gk-math\" data-tex=\"0\\leq x\\leq y\\leq\\dfrac h2\">0\\leq x\\leq y\\leq\\dfrac h2</span> 时，该部分为一个三棱锥，其四个顶点为 <span class=\"gk-math\" data-tex=\"B\">B</span>、<span class=\"gk-math\" data-tex=\"M=\\left(0,\\dfrac h2,0\\right)\">M=\\left(0,\\dfrac h2,0\\right)</span>、<span class=\"gk-math\" data-tex=\"G\">G</span> 以及 <span class=\"gk-math\" data-tex=\"H=\\left(\\dfrac h2,\\dfrac h2,\\dfrac{h}{2\\sqrt3}\\right)\">H=\\left(\\dfrac h2,\\dfrac h2,\\dfrac{h}{2\\sqrt3}\\right)</span>. 其底面 <span class=\"gk-math\" data-tex=\"\\triangle MGH\">\\triangle MGH</span> 在平面 <span class=\"gk-math\" data-tex=\"y=\\dfrac h2\">y=\\dfrac h2</span> 内，且<br><br><div class=\"gk-math display\" data-tex=\"S_{\\triangle MGH}=\\frac12\\cdot\\frac h2\\cdot\\frac{h}{2\\sqrt3}=\\frac{h^2}{8\\sqrt3}\">S_{\\triangle MGH}=\\frac12\\cdot\\frac h2\\cdot\\frac{h}{2\\sqrt3}=\\frac{h^2}{8\\sqrt3}</div><br><br>顶点 <span class=\"gk-math\" data-tex=\"B\">B</span> 到该底面的距离为 <span class=\"gk-math\" data-tex=\"\\dfrac h2\">\\dfrac h2</span>，所以该三棱锥的体积为<br><br><div class=\"gk-math display\" data-tex=\"V_1=\\frac13\\cdot\\frac{h^2}{8\\sqrt3}\\cdot\\frac h2=\\frac{h^3}{48\\sqrt3}\">V_1=\\frac13\\cdot\\frac{h^2}{8\\sqrt3}\\cdot\\frac h2=\\frac{h^3}{48\\sqrt3}</div><br><br>由关于 <span class=\"gk-math\" data-tex=\"x=\\dfrac h2\">x=\\dfrac h2</span> 和 <span class=\"gk-math\" data-tex=\"y=\\dfrac h2\">y=\\dfrac h2</span> 的对称性，第二个棱柱在第一个棱柱外的部分由 4 个全等的上述三棱锥组成. 因此<br><br><div class=\"gk-math display\" data-tex=\"V=Sh+4V_1\n=\\frac{9\\sqrt3}{4}\\cdot3\\sqrt3+4\\cdot\\frac{(3\\sqrt3)^3}{48\\sqrt3}\n=\\frac{81}{4}+\\frac{27}{4}=27\">V=Sh+4V_1\n=\\frac{9\\sqrt3}{4}\\cdot3\\sqrt3+4\\cdot\\frac{(3\\sqrt3)^3}{48\\sqrt3}\n=\\frac{81}{4}+\\frac{27}{4}=27</div> 故选 C.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-tianjin-q09","paperId":"2022-tianjin","number":9,"type":"single","score":5,"lessonIds":["5.4","5.6"],"difficulty":"进阶","hint":"把角2x看成一个整体，逐条检查周期、递增区间、区间内最高点和平移方向。","legacy":false,"legacyReason":"","searchText":"关于函数 f(x)=\\dfrac{1}{2}\\sin 2x ，给出下列结论： f(x) 的最小正周期是 2\\pi ； f(x) 在区间 \\left[-\\dfrac{\\pi}{4},\\dfrac{\\pi}{4}\\right] 上单调递增； 当 x\\in\\left[-\\dfrac{\\pi}{6},\\dfrac{\\pi}{3}\\right] 时， f(x) 的取值范围为 \\left[-\\dfrac{\\sqrt{3}}{4},\\dfrac{\\sqrt{3}}{4}\\right] ； f(x) 的图象可以由函数 g(x)=\\dfrac{1}{2}\\sin\\left(2x+\\dfrac{\\pi}{4}\\right) 的图象向左平移 \\dfrac{\\pi}{8} 个单位长度得到. 其中正确结论的个数为（ ） 1 2 3 4","questionHtml":"关于函数 <span class=\"gk-math\" data-tex=\"f(x)=\\dfrac{1}{2}\\sin 2x\">f(x)=\\dfrac{1}{2}\\sin 2x</span>，给出下列结论：<br><br><ol class=\"gk-subparts\"><li><span class=\"gk-math\" data-tex=\"f(x)\">f(x)</span> 的最小正周期是 <span class=\"gk-math\" data-tex=\"2\\pi\">2\\pi</span>；</li><li><span class=\"gk-math\" data-tex=\"f(x)\">f(x)</span> 在区间 <span class=\"gk-math\" data-tex=\"\\left[-\\dfrac{\\pi}{4},\\dfrac{\\pi}{4}\\right]\">\\left[-\\dfrac{\\pi}{4},\\dfrac{\\pi}{4}\\right]</span> 上单调递增；</li><li>当 <span class=\"gk-math\" data-tex=\"x\\in\\left[-\\dfrac{\\pi}{6},\\dfrac{\\pi}{3}\\right]\">x\\in\\left[-\\dfrac{\\pi}{6},\\dfrac{\\pi}{3}\\right]</span> 时，<span class=\"gk-math\" data-tex=\"f(x)\">f(x)</span> 的取值范围为 <span class=\"gk-math\" data-tex=\"\\left[-\\dfrac{\\sqrt{3}}{4},\\dfrac{\\sqrt{3}}{4}\\right]\">\\left[-\\dfrac{\\sqrt{3}}{4},\\dfrac{\\sqrt{3}}{4}\\right]</span>；</li><li><span class=\"gk-math\" data-tex=\"f(x)\">f(x)</span> 的图象可以由函数 <span class=\"gk-math\" data-tex=\"g(x)=\\dfrac{1}{2}\\sin\\left(2x+\\dfrac{\\pi}{4}\\right)\">g(x)=\\dfrac{1}{2}\\sin\\left(2x+\\dfrac{\\pi}{4}\\right)</span> 的图象向左平移 <span class=\"gk-math\" data-tex=\"\\dfrac{\\pi}{8}\">\\dfrac{\\pi}{8}</span> 个单位长度得到.</li></ol> 其中正确结论的个数为（ ）","optionsHtml":["1","2","3","4"],"answerHtml":"A","answerKey":"A","solutionHtml":"函数 <span class=\"gk-math\" data-tex=\"f(x)=\\dfrac12\\sin2x\">f(x)=\\dfrac12\\sin2x</span> 的最小正周期为 <span class=\"gk-math\" data-tex=\"\\pi\">\\pi</span>，所以结论 1 错误.<br><br>在区间 <span class=\"gk-math\" data-tex=\"\\left[-\\dfrac\\pi4,\\dfrac\\pi4\\right]\">\\left[-\\dfrac\\pi4,\\dfrac\\pi4\\right]</span> 上，<span class=\"gk-math\" data-tex=\"2x\\in\\left[-\\dfrac\\pi2,\\dfrac\\pi2\\right]\">2x\\in\\left[-\\dfrac\\pi2,\\dfrac\\pi2\\right]</span>，正弦函数在该区间上单调递增，所以结论 2 正确.<br><br>当 <span class=\"gk-math\" data-tex=\"x\\in\\left[-\\dfrac\\pi6,\\dfrac\\pi3\\right]\">x\\in\\left[-\\dfrac\\pi6,\\dfrac\\pi3\\right]</span> 时，<span class=\"gk-math\" data-tex=\"2x\\in\\left[-\\dfrac\\pi3,\\dfrac{2\\pi}3\\right]\">2x\\in\\left[-\\dfrac\\pi3,\\dfrac{2\\pi}3\\right]</span>. 在此区间上，<span class=\"gk-math\" data-tex=\"\\sin2x\">\\sin2x</span> 的最小值为 <span class=\"gk-math\" data-tex=\"-\\dfrac{\\sqrt3}{2}\">-\\dfrac{\\sqrt3}{2}</span>，最大值为 <span class=\"gk-math\" data-tex=\"1\">1</span>，故 <span class=\"gk-math\" data-tex=\"f(x)\\in\\left[-\\dfrac{\\sqrt3}{4},\\dfrac12\\right]\">f(x)\\in\\left[-\\dfrac{\\sqrt3}{4},\\dfrac12\\right]</span>，不是题给范围，结论 3 错误.<br><br>又 <span class=\"gk-math\" data-tex=\"g\\left(x-\\dfrac\\pi8\\right)=\\dfrac12\\sin\\left(2x-\\dfrac\\pi4+\\dfrac\\pi4\\right)=f(x)\">g\\left(x-\\dfrac\\pi8\\right)=\\dfrac12\\sin\\left(2x-\\dfrac\\pi4+\\dfrac\\pi4\\right)=f(x)</span>，所以 <span class=\"gk-math\" data-tex=\"f(x)\">f(x)</span> 的图象由 <span class=\"gk-math\" data-tex=\"g(x)\">g(x)</span> 的图象向右平移 <span class=\"gk-math\" data-tex=\"\\dfrac\\pi8\">\\dfrac\\pi8</span> 个单位长度得到，结论 4 错误. 正确结论只有 1 个，故选 A.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-tianjin-q10","paperId":"2022-tianjin","number":10,"type":"fill","score":5,"lessonIds":["7.2"],"difficulty":"基础","hint":"分子分母同时乘1−2i，让分母变成实数，最后把实部和虚部分开。","legacy":false,"legacyReason":"","searchText":"已知 \\i 是虚数单位，化简 \\dfrac{11-3\\i}{1+2\\i} 的结果为 ________ . ","questionHtml":"已知 <span class=\"gk-math\" data-tex=\"\\i\">\\i</span> 是虚数单位，化简 <span class=\"gk-math\" data-tex=\"\\dfrac{11-3\\i}{1+2\\i}\">\\dfrac{11-3\\i}{1+2\\i}</span> 的结果为<span class=\"gk-blank\" aria-label=\"填空\">________</span>.","optionsHtml":[],"answerHtml":"<span class=\"gk-math\" data-tex=\"1-5\\i\">1-5\\i</span>","answerKey":"","solutionHtml":"分子、分母同乘分母的共轭复数 <span class=\"gk-math\" data-tex=\"1-2\\i\">1-2\\i</span>，得 <div class=\"gk-math display\" data-tex=\"\\frac{11-3\\i}{1+2\\i}\n=\\frac{(11-3\\i)(1-2\\i)}{(1+2\\i)(1-2\\i)}\n=\\frac{11-22\\i-3\\i+6\\i^2}{5}\n=\\frac{5-25\\i}{5}=1-5\\i\">\\frac{11-3\\i}{1+2\\i}\n=\\frac{(11-3\\i)(1-2\\i)}{(1+2\\i)(1-2\\i)}\n=\\frac{11-22\\i-3\\i+6\\i^2}{5}\n=\\frac{5-25\\i}{5}=1-5\\i</div>","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-tianjin-q11","paperId":"2022-tianjin","number":11,"type":"fill","score":5,"lessonIds":["e3-6.3"],"difficulty":"基础","hint":"写展开式的第k+1项，把x的指数整理出来。常数项就是指数等于0的那一项。","legacy":false,"legacyReason":"","searchText":"在 \\left(\\sqrt{x}+\\dfrac{3}{x^2}\\right)^5 的展开式中，常数项是 ________ . ","questionHtml":"在 <span class=\"gk-math\" data-tex=\"\\left(\\sqrt{x}+\\dfrac{3}{x^2}\\right)^5\">\\left(\\sqrt{x}+\\dfrac{3}{x^2}\\right)^5</span> 的展开式中，常数项是<span class=\"gk-blank\" aria-label=\"填空\">________</span>.","optionsHtml":[],"answerHtml":"15","answerKey":"","solutionHtml":"展开式的通项为 <div class=\"gk-math display\" data-tex=\"\\mathrm C_5^r(\\sqrt{x})^r\\left(\\frac{3}{x^2}\\right)^{5-r}\n=\\mathrm C_5^r3^{5-r}x^{\\frac r2-2(5-r)}\n=\\mathrm C_5^r3^{5-r}x^{\\frac{5r}{2}-10}\">\\mathrm C_5^r(\\sqrt{x})^r\\left(\\frac{3}{x^2}\\right)^{5-r}\n=\\mathrm C_5^r3^{5-r}x^{\\frac r2-2(5-r)}\n=\\mathrm C_5^r3^{5-r}x^{\\frac{5r}{2}-10}</div> 要得到常数项，必须有 <span class=\"gk-math\" data-tex=\"\\dfrac{5r}{2}-10=0\">\\dfrac{5r}{2}-10=0</span>，即 <span class=\"gk-math\" data-tex=\"r=4\">r=4</span>. 所以常数项为 <span class=\"gk-math\" data-tex=\"\\mathrm C_5^4\\cdot3=15\">\\mathrm C_5^4\\cdot3=15</span>.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-tianjin-q12","paperId":"2022-tianjin","number":12,"type":"fill","score":5,"lessonIds":["e1-2.5","e1-2.3"],"difficulty":"进阶","hint":"从圆心向弦作垂线。半弦长是m/2，圆心到直线的距离也能用m表示，再列勾股式。","legacy":false,"legacyReason":"","searchText":"若直线 x-y+m=0 （ m>0 ）被圆 (x-1)^2+(y-1)^2=3 截得的弦长等于 m ，则 m 的值为 ________ . ","questionHtml":"若直线 <span class=\"gk-math\" data-tex=\"x-y+m=0\">x-y+m=0</span>（<span class=\"gk-math\" data-tex=\"m&gt;0\">m&gt;0</span>）被圆 <span class=\"gk-math\" data-tex=\"(x-1)^2+(y-1)^2=3\">(x-1)^2+(y-1)^2=3</span> 截得的弦长等于 <span class=\"gk-math\" data-tex=\"m\">m</span>，则 <span class=\"gk-math\" data-tex=\"m\">m</span> 的值为<span class=\"gk-blank\" aria-label=\"填空\">________</span>.","optionsHtml":[],"answerHtml":"2","answerKey":"","solutionHtml":"圆心为 <span class=\"gk-math\" data-tex=\"O(1,1)\">O(1,1)</span>，半径为 <span class=\"gk-math\" data-tex=\"r=\\sqrt3\">r=\\sqrt3</span>. 圆心到直线的距离为 <div class=\"gk-math display\" data-tex=\"d=\\frac{|1-1+m|}{\\sqrt{1^2+(-1)^2}}=\\frac{m}{\\sqrt2}\">d=\\frac{|1-1+m|}{\\sqrt{1^2+(-1)^2}}=\\frac{m}{\\sqrt2}</div> 由弦长公式， <div class=\"gk-math display\" data-tex=\"m=2\\sqrt{r^2-d^2}=2\\sqrt{3-\\frac{m^2}{2}}\">m=2\\sqrt{r^2-d^2}=2\\sqrt{3-\\frac{m^2}{2}}</div> 两边平方得 <span class=\"gk-math\" data-tex=\"m^2=12-2m^2\">m^2=12-2m^2</span>，所以 <span class=\"gk-math\" data-tex=\"m^2=4\">m^2=4</span>. 又 <span class=\"gk-math\" data-tex=\"m&gt;0\">m&gt;0</span>，故 <span class=\"gk-math\" data-tex=\"m=2\">m=2</span>.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-tianjin-q13","paperId":"2022-tianjin","number":13,"type":"fill","score":5,"lessonIds":["10.1","e3-7.1"],"difficulty":"基础","hint":"不放回意味着第二次只剩51张。第一空要同时乘两次概率，第二空已经知道第一次是A。","legacy":false,"legacyReason":"","searchText":"现有 52 张扑克牌（去掉大小王），每次取一张，取后不放回，则两次都抽到 A 的概率为 ________ ；在第一次抽到 A 的条件下，第二次也抽到 A 的概率为 ________ . ","questionHtml":"现有 52 张扑克牌（去掉大小王），每次取一张，取后不放回，则两次都抽到 <span class=\"gk-math\" data-tex=\"A\">A</span> 的概率为<span class=\"gk-blank\" aria-label=\"填空\">________</span>；在第一次抽到 <span class=\"gk-math\" data-tex=\"A\">A</span> 的条件下，第二次也抽到 <span class=\"gk-math\" data-tex=\"A\">A</span> 的概率为<span class=\"gk-blank\" aria-label=\"填空\">________</span>.","optionsHtml":[],"answerHtml":"<span class=\"gk-math\" data-tex=\"\\dfrac{1}{221}\">\\dfrac{1}{221}</span>；<span class=\"gk-math\" data-tex=\"\\dfrac{1}{17}\">\\dfrac{1}{17}</span>","answerKey":"","solutionHtml":"52 张牌中有 4 张 <span class=\"gk-math\" data-tex=\"A\">A</span>. 两次都抽到 <span class=\"gk-math\" data-tex=\"A\">A</span> 的概率为 <div class=\"gk-math display\" data-tex=\"\\frac4{52}\\cdot\\frac3{51}=\\frac1{221}\">\\frac4{52}\\cdot\\frac3{51}=\\frac1{221}</div> 在第一次抽到 <span class=\"gk-math\" data-tex=\"A\">A</span> 的条件下，剩余 51 张牌中有 3 张 <span class=\"gk-math\" data-tex=\"A\">A</span>，所以第二次也抽到 <span class=\"gk-math\" data-tex=\"A\">A</span> 的条件概率为 <div class=\"gk-math display\" data-tex=\"\\frac3{51}=\\frac1{17}\">\\frac3{51}=\\frac1{17}</div>","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-tianjin-q14","paperId":"2022-tianjin","number":14,"type":"fill","score":5,"lessonIds":["6.2","6.4","2.2"],"difficulty":"进阶","hint":"先沿C→B→E写出CE，再减CD得到DE。垂直时两向量数量积为0，再研究夹角大小。","legacy":false,"legacyReason":"","searchText":"在 \\triangle ABC 中，点 D 为 AC 的中点，点 E 满足 \\overrightarrow{CB}=2\\overrightarrow{BE} . 记 \\overrightarrow{CA}=\\bs{a} ， \\overrightarrow{CB}=\\bs{b} ，用 \\bs{a} ， \\bs{b} 表示 \\overrightarrow{DE}= ________ ；若 \\overrightarrow{AB}\\perp\\overrightarrow{DE} ，则 \\angle ACB 的最大值为 ________ . ","questionHtml":"在 <span class=\"gk-math\" data-tex=\"\\triangle ABC\">\\triangle ABC</span> 中，点 <span class=\"gk-math\" data-tex=\"D\">D</span> 为 <span class=\"gk-math\" data-tex=\"AC\">AC</span> 的中点，点 <span class=\"gk-math\" data-tex=\"E\">E</span> 满足 <span class=\"gk-math\" data-tex=\"\\overrightarrow{CB}=2\\overrightarrow{BE}\">\\overrightarrow{CB}=2\\overrightarrow{BE}</span>. 记 <span class=\"gk-math\" data-tex=\"\\overrightarrow{CA}=\\bs{a}\">\\overrightarrow{CA}=\\bs{a}</span>，<span class=\"gk-math\" data-tex=\"\\overrightarrow{CB}=\\bs{b}\">\\overrightarrow{CB}=\\bs{b}</span>，用 <span class=\"gk-math\" data-tex=\"\\bs{a}\">\\bs{a}</span>，<span class=\"gk-math\" data-tex=\"\\bs{b}\">\\bs{b}</span> 表示 <span class=\"gk-math\" data-tex=\"\\overrightarrow{DE}=\">\\overrightarrow{DE}=</span><span class=\"gk-blank\" aria-label=\"填空\">________</span>；若 <span class=\"gk-math\" data-tex=\"\\overrightarrow{AB}\\perp\\overrightarrow{DE}\">\\overrightarrow{AB}\\perp\\overrightarrow{DE}</span>，则 <span class=\"gk-math\" data-tex=\"\\angle ACB\">\\angle ACB</span> 的最大值为<span class=\"gk-blank\" aria-label=\"填空\">________</span>.","optionsHtml":[],"answerHtml":"<span class=\"gk-math\" data-tex=\"\\dfrac{3}{2}\\bs{b}-\\dfrac{1}{2}\\bs{a}\">\\dfrac{3}{2}\\bs{b}-\\dfrac{1}{2}\\bs{a}</span>；<span class=\"gk-math\" data-tex=\"\\dfrac{\\pi}{6}\">\\dfrac{\\pi}{6}</span>","answerKey":"","solutionHtml":"以 <span class=\"gk-math\" data-tex=\"C\">C</span> 为起点，用位置向量表示各点，则 <span class=\"gk-math\" data-tex=\"\\overrightarrow{CA}=\\bs a\">\\overrightarrow{CA}=\\bs a</span>，<span class=\"gk-math\" data-tex=\"\\overrightarrow{CB}=\\bs b\">\\overrightarrow{CB}=\\bs b</span>，且 <span class=\"gk-math\" data-tex=\"D\">D</span> 为 <span class=\"gk-math\" data-tex=\"AC\">AC</span> 的中点，所以 <span class=\"gk-math\" data-tex=\"\\overrightarrow{CD}=\\dfrac12\\bs a\">\\overrightarrow{CD}=\\dfrac12\\bs a</span>. 由 <span class=\"gk-math\" data-tex=\"\\overrightarrow{CB}=2\\overrightarrow{BE}\">\\overrightarrow{CB}=2\\overrightarrow{BE}</span>，得 <span class=\"gk-math\" data-tex=\"\\overrightarrow{BE}=\\dfrac12\\bs b\">\\overrightarrow{BE}=\\dfrac12\\bs b</span>，从而 <span class=\"gk-math\" data-tex=\"\\overrightarrow{CE}=\\overrightarrow{CB}+\\overrightarrow{BE}=\\dfrac32\\bs b\">\\overrightarrow{CE}=\\overrightarrow{CB}+\\overrightarrow{BE}=\\dfrac32\\bs b</span>. 因此 <div class=\"gk-math display\" data-tex=\"\\overrightarrow{DE}=\\overrightarrow{CE}-\\overrightarrow{CD}\n=\\frac32\\bs b-\\frac12\\bs a\">\\overrightarrow{DE}=\\overrightarrow{CE}-\\overrightarrow{CD}\n=\\frac32\\bs b-\\frac12\\bs a</div><br><br>又 <span class=\"gk-math\" data-tex=\"\\overrightarrow{AB}=\\bs b-\\bs a\">\\overrightarrow{AB}=\\bs b-\\bs a</span>，所以垂直条件给出 <div class=\"gk-math display\" data-tex=\"(\\bs b-\\bs a)\\cdot(3\\bs b-\\bs a)=0\">(\\bs b-\\bs a)\\cdot(3\\bs b-\\bs a)=0</div> 即 <div class=\"gk-math display\" data-tex=\"3|\\bs b|^2+|\\bs a|^2-4\\bs a\\cdot\\bs b=0\">3|\\bs b|^2+|\\bs a|^2-4\\bs a\\cdot\\bs b=0</div> 设 <span class=\"gk-math\" data-tex=\"\\theta=\\angle ACB\">\\theta=\\angle ACB</span>，并令 <span class=\"gk-math\" data-tex=\"t=\\dfrac{|\\bs a|}{|\\bs b|}&gt;0\">t=\\dfrac{|\\bs a|}{|\\bs b|}&gt;0</span>. 由 <span class=\"gk-math\" data-tex=\"\\bs a\\cdot\\bs b=|\\bs a||\\bs b|\\cos\\theta\">\\bs a\\cdot\\bs b=|\\bs a||\\bs b|\\cos\\theta</span>，上式化为 <div class=\"gk-math display\" data-tex=\"t^2-4t\\cos\\theta+3=0\">t^2-4t\\cos\\theta+3=0</div> 因此 <span class=\"gk-math\" data-tex=\"4t\\cos\\theta=t^2+3&gt;0\">4t\\cos\\theta=t^2+3&gt;0</span>，从而 <span class=\"gk-math\" data-tex=\"\\cos\\theta&gt;0\">\\cos\\theta&gt;0</span>. 该关于 <span class=\"gk-math\" data-tex=\"t\">t</span> 的方程有正实根，判别式必须满足 <div class=\"gk-math display\" data-tex=\"16\\cos^2\\theta-12\\geq0\">16\\cos^2\\theta-12\\geq0</div> 结合 <span class=\"gk-math\" data-tex=\"\\cos\\theta&gt;0\">\\cos\\theta&gt;0</span> 和 <span class=\"gk-math\" data-tex=\"0&lt;\\theta&lt;\\pi\">0&lt;\\theta&lt;\\pi</span>，得 <span class=\"gk-math\" data-tex=\"\\cos\\theta\\geq\\dfrac{\\sqrt3}{2}\">\\cos\\theta\\geq\\dfrac{\\sqrt3}{2}</span>，所以 <span class=\"gk-math\" data-tex=\"\\theta\\leq\\dfrac\\pi6\">\\theta\\leq\\dfrac\\pi6</span>. 当 <span class=\"gk-math\" data-tex=\"\\cos\\theta=\\dfrac{\\sqrt3}{2}\">\\cos\\theta=\\dfrac{\\sqrt3}{2}</span>、<span class=\"gk-math\" data-tex=\"t=\\sqrt3\">t=\\sqrt3</span> 时等号可以取得，故最大值为 <span class=\"gk-math\" data-tex=\"\\dfrac\\pi6\">\\dfrac\\pi6</span>.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-tianjin-q15","paperId":"2022-tianjin","number":15,"type":"fill","score":5,"lessonIds":["3.1","3.4","2.3"],"difficulty":"挑战","hint":"较小者等于0时，两个式子都不能为负。先检查x=±2，再找二次式在|x|大于2处的根。","legacy":false,"legacyReason":"","searchText":"设 a\\in\\R ，对任意实数 x ，记 f(x) 表示 |x|-2 ， x^2-ax+3a-5 中的较小者. 若函数 f(x) 至少有 3 个零点，则 a 的取值范围为 ________ . ","questionHtml":"设 <span class=\"gk-math\" data-tex=\"a\\in\\R\">a\\in\\R</span>，对任意实数 <span class=\"gk-math\" data-tex=\"x\">x</span>，记 <span class=\"gk-math\" data-tex=\"f(x)\">f(x)</span> 表示 <span class=\"gk-math\" data-tex=\"|x|-2\">|x|-2</span>，<span class=\"gk-math\" data-tex=\"x^2-ax+3a-5\">x^2-ax+3a-5</span> 中的较小者. 若函数 <span class=\"gk-math\" data-tex=\"f(x)\">f(x)</span> 至少有 3 个零点，则 <span class=\"gk-math\" data-tex=\"a\">a</span> 的取值范围为<span class=\"gk-blank\" aria-label=\"填空\">________</span>.","optionsHtml":[],"answerHtml":"<span class=\"gk-math\" data-tex=\"[10,+\\infty)\">[10,+\\infty)</span>","answerKey":"","solutionHtml":"令 <span class=\"gk-math\" data-tex=\"p(x)=|x|-2\">p(x)=|x|-2</span>，<span class=\"gk-math\" data-tex=\"q(x)=x^2-ax+3a-5\">q(x)=x^2-ax+3a-5</span>. 因为 <span class=\"gk-math\" data-tex=\"f(x)=\\min\\{p(x),q(x)\\}\">f(x)=\\min\\{p(x),q(x)\\}</span>，所以 <span class=\"gk-math\" data-tex=\"f(x)=0\">f(x)=0</span> 当且仅当 <span class=\"gk-math\" data-tex=\"p(x)\\geq0\">p(x)\\geq0</span>，<span class=\"gk-math\" data-tex=\"q(x)\\geq0\">q(x)\\geq0</span>，且 <span class=\"gk-math\" data-tex=\"p(x)=0\">p(x)=0</span> 或 <span class=\"gk-math\" data-tex=\"q(x)=0\">q(x)=0</span>.<br><br>当 <span class=\"gk-math\" data-tex=\"p(x)=0\">p(x)=0</span> 时，<span class=\"gk-math\" data-tex=\"x=\\pm2\">x=\\pm2</span>. 分别计算 <span class=\"gk-math\" data-tex=\"q(2)=a-1\">q(2)=a-1</span>，<span class=\"gk-math\" data-tex=\"q(-2)=5a-1\">q(-2)=5a-1</span>. 因此 <span class=\"gk-math\" data-tex=\"x=2\">x=2</span> 是零点的条件为 <span class=\"gk-math\" data-tex=\"a\\geq1\">a\\geq1</span>，<span class=\"gk-math\" data-tex=\"x=-2\">x=-2</span> 是零点的条件为 <span class=\"gk-math\" data-tex=\"a\\geq\\dfrac15\">a\\geq\\dfrac15</span>.<br><br>其余零点必须是方程 <span class=\"gk-math\" data-tex=\"q(x)=0\">q(x)=0</span> 且满足 <span class=\"gk-math\" data-tex=\"|x|&gt;2\">|x|&gt;2</span> 的根. 方程 <span class=\"gk-math\" data-tex=\"q(x)=0\">q(x)=0</span> 的判别式为 <div class=\"gk-math display\" data-tex=\"\\Delta=a^2-4(3a-5)=(a-2)(a-10)\">\\Delta=a^2-4(3a-5)=(a-2)(a-10)</div> 当 <span class=\"gk-math\" data-tex=\"a&lt;2\">a&lt;2</span> 时，二次函数的顶点横坐标为 <span class=\"gk-math\" data-tex=\"\\dfrac a2&lt;1\">\\dfrac a2&lt;1</span>，所以在 <span class=\"gk-math\" data-tex=\"x\\geq2\">x\\geq2</span> 上严格递增，方程 <span class=\"gk-math\" data-tex=\"q(x)=0\">q(x)=0</span> 在 <span class=\"gk-math\" data-tex=\"x&gt;2\">x&gt;2</span> 上至多有一个根；若有这样的根，则 <span class=\"gk-math\" data-tex=\"q(2)&lt;0\">q(2)&lt;0</span>，从而 <span class=\"gk-math\" data-tex=\"x=2\">x=2</span> 不是 <span class=\"gk-math\" data-tex=\"f\">f</span> 的零点. 在 <span class=\"gk-math\" data-tex=\"x\\leq-2\">x\\leq-2</span> 上，若 <span class=\"gk-math\" data-tex=\"a\\geq-4\">a\\geq-4</span>，则 <span class=\"gk-math\" data-tex=\"q&#x27;(x)=2x-a\\leq-4-a\\leq0\">q&#x27;(x)=2x-a\\leq-4-a\\leq0</span>，方程 <span class=\"gk-math\" data-tex=\"q(x)=0\">q(x)=0</span> 在 <span class=\"gk-math\" data-tex=\"x&lt;-2\">x&lt;-2</span> 上至多有一个根；若 <span class=\"gk-math\" data-tex=\"a&lt;-4\">a&lt;-4</span>，则顶点在 <span class=\"gk-math\" data-tex=\"-2\">-2</span> 的左侧，且 <span class=\"gk-math\" data-tex=\"q(-2)=5a-1&lt;0\">q(-2)=5a-1&lt;0</span>，所以左支至多有一个根落在 <span class=\"gk-math\" data-tex=\"x&lt;-2\">x&lt;-2</span>，另一个根若存在则大于 <span class=\"gk-math\" data-tex=\"-2\">-2</span>. 因此 <span class=\"gk-math\" data-tex=\"q(x)=0\">q(x)=0</span> 在 <span class=\"gk-math\" data-tex=\"|x|&gt;2\">|x|&gt;2</span> 上至多有两个根，且一旦有 <span class=\"gk-math\" data-tex=\"x&lt;-2\">x&lt;-2</span> 的根，就有 <span class=\"gk-math\" data-tex=\"q(-2)&lt;0\">q(-2)&lt;0</span>，从而 <span class=\"gk-math\" data-tex=\"x=-2\">x=-2</span> 也不是 <span class=\"gk-math\" data-tex=\"f\">f</span> 的零点. 结合 <span class=\"gk-math\" data-tex=\"x=\\pm2\">x=\\pm2</span> 的情况可知，此时至多得到两个零点，不能满足至少 3 个零点的要求.<br><br>当 <span class=\"gk-math\" data-tex=\"a=2\">a=2</span> 时，<span class=\"gk-math\" data-tex=\"q(x)=(x-1)^2\">q(x)=(x-1)^2</span>，其唯一零点 <span class=\"gk-math\" data-tex=\"x=1\">x=1</span> 不满足 <span class=\"gk-math\" data-tex=\"p(x)\\geq0\">p(x)\\geq0</span>，所以仍只有 <span class=\"gk-math\" data-tex=\"x=\\pm2\">x=\\pm2</span> 两个零点. 当 <span class=\"gk-math\" data-tex=\"2&lt;a&lt;10\">2&lt;a&lt;10</span> 时，<span class=\"gk-math\" data-tex=\"\\Delta&lt;0\">\\Delta&lt;0</span>，故 <span class=\"gk-math\" data-tex=\"q(x)&gt;0\">q(x)&gt;0</span> 对任意 <span class=\"gk-math\" data-tex=\"x\">x</span> 成立，只有 <span class=\"gk-math\" data-tex=\"x=\\pm2\">x=\\pm2</span> 两个零点. <span class=\"gk-math\" data-tex=\"a=10\">a=10</span> 时， <span class=\"gk-math\" data-tex=\"q(x)=x^2-10x+25=(x-5)^2\">q(x)=x^2-10x+25=(x-5)^2</span>，所以 <span class=\"gk-math\" data-tex=\"x=-2\">x=-2</span>，<span class=\"gk-math\" data-tex=\"x=2\">x=2</span> 和 <span class=\"gk-math\" data-tex=\"x=5\">x=5</span> 均为零点，恰有 3 个零点.<br><br>当 <span class=\"gk-math\" data-tex=\"a&gt;10\">a&gt;10</span> 时，方程 <span class=\"gk-math\" data-tex=\"q(x)=0\">q(x)=0</span> 有两个根 <div class=\"gk-math display\" data-tex=\"x_{1,2}=\\frac{a\\mp\\sqrt{(a-2)(a-10)}}2\">x_{1,2}=\\frac{a\\mp\\sqrt{(a-2)(a-10)}}2</div> 其中较小根满足 <span class=\"gk-math\" data-tex=\"x_1&gt;2\">x_1&gt;2</span>：因为 <span class=\"gk-math\" data-tex=\"x_1&gt;2\">x_1&gt;2</span> 等价于 <span class=\"gk-math\" data-tex=\"a-4&gt;\\sqrt{(a-2)(a-10)}\">a-4&gt;\\sqrt{(a-2)(a-10)}</span>，而 <span class=\"gk-math\" data-tex=\"a&gt;10\">a&gt;10</span> 时两边均为正，平方后等价于 <span class=\"gk-math\" data-tex=\"4(a-1)&gt;0\">4(a-1)&gt;0</span>. 故两个根都大于 2，再加上 <span class=\"gk-math\" data-tex=\"x=\\pm2\">x=\\pm2</span>，零点数至少为 4.<br><br>综上，函数至少有 3 个零点当且仅当 <span class=\"gk-math\" data-tex=\"a\\geq10\">a\\geq10</span>，故填 <span class=\"gk-math\" data-tex=\"[10,+\\infty)\">[10,+\\infty)</span>.","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-tianjin-q16","paperId":"2022-tianjin","number":16,"type":"written","score":14,"lessonIds":["6.4","5.5"],"difficulty":"进阶","hint":"先把b=2c代入余弦定理求c；接着用正弦定理求sin B，最后展开sin(2A−B)。","legacy":false,"legacyReason":"","searchText":"在 \\triangle ABC 中，角 A ， B ， C 所对的边分别为 a ， b ， c . 已知 a=\\sqrt{6} ， b=2c ， \\cos A=-\\dfrac{1}{4} . 求 c 的值； 求 \\sin B 的值； 求 \\sin(2A-B) 的值. ","questionHtml":"在 <span class=\"gk-math\" data-tex=\"\\triangle ABC\">\\triangle ABC</span> 中，角 <span class=\"gk-math\" data-tex=\"A\">A</span>，<span class=\"gk-math\" data-tex=\"B\">B</span>，<span class=\"gk-math\" data-tex=\"C\">C</span> 所对的边分别为 <span class=\"gk-math\" data-tex=\"a\">a</span>，<span class=\"gk-math\" data-tex=\"b\">b</span>，<span class=\"gk-math\" data-tex=\"c\">c</span>. 已知 <span class=\"gk-math\" data-tex=\"a=\\sqrt{6}\">a=\\sqrt{6}</span>，<span class=\"gk-math\" data-tex=\"b=2c\">b=2c</span>，<span class=\"gk-math\" data-tex=\"\\cos A=-\\dfrac{1}{4}\">\\cos A=-\\dfrac{1}{4}</span>.<br><br><ol class=\"gk-subparts\"><li>求 <span class=\"gk-math\" data-tex=\"c\">c</span> 的值；</li><li>求 <span class=\"gk-math\" data-tex=\"\\sin B\">\\sin B</span> 的值；</li><li>求 <span class=\"gk-math\" data-tex=\"\\sin(2A-B)\">\\sin(2A-B)</span> 的值.</li></ol>","optionsHtml":[],"answerHtml":"（1）<span class=\"gk-math\" data-tex=\"c=1\">c=1</span>；（2）<span class=\"gk-math\" data-tex=\"\\sin B=\\frac{\\sqrt{10}}4\">\\sin B=\\frac{\\sqrt{10}}4</span>；（3）<span class=\"gk-math\" data-tex=\"\\sin(2A-B)=\\frac{\\sqrt{10}}8\">\\sin(2A-B)=\\frac{\\sqrt{10}}8</span>.","answerKey":"","solutionHtml":"<ol class=\"gk-subparts\"><li>由余弦定理，<span class=\"gk-math\" data-tex=\"a^2=b^2+c^2-2bc\\cos A\">a^2=b^2+c^2-2bc\\cos A</span>. 代入 <span class=\"gk-math\" data-tex=\"a=\\sqrt6\">a=\\sqrt6</span>，<span class=\"gk-math\" data-tex=\"b=2c\">b=2c</span>，<span class=\"gk-math\" data-tex=\"\\cos A=-\\dfrac14\">\\cos A=-\\dfrac14</span>，得 <span class=\"gk-math\" data-tex=\"6=4c^2+c^2+c^2=6c^2\">6=4c^2+c^2+c^2=6c^2</span>. 由于边长 <span class=\"gk-math\" data-tex=\"c&gt;0\">c&gt;0</span>，所以 <span class=\"gk-math\" data-tex=\"c=1\">c=1</span>.</li><li>由 <span class=\"gk-math\" data-tex=\"a=\\sqrt6\">a=\\sqrt6</span> 及 <span class=\"gk-math\" data-tex=\"\\cos A=-\\dfrac14\">\\cos A=-\\dfrac14</span>，得 <span class=\"gk-math\" data-tex=\"\\sin A=\\sqrt{1-\\cos^2A}=\\dfrac{\\sqrt{15}}4\">\\sin A=\\sqrt{1-\\cos^2A}=\\dfrac{\\sqrt{15}}4</span>. 由正弦定理，<span class=\"gk-math\" data-tex=\"\\dfrac{\\sin B}{b}=\\dfrac{\\sin A}{a}\">\\dfrac{\\sin B}{b}=\\dfrac{\\sin A}{a}</span>，又 <span class=\"gk-math\" data-tex=\"b=2\">b=2</span>，所以 <span class=\"gk-math\" data-tex=\"\\sin B=\\dfrac{2\\cdot\\frac{\\sqrt{15}}{4}}{\\sqrt6}=\\dfrac{\\sqrt{10}}4\">\\sin B=\\dfrac{2\\cdot\\frac{\\sqrt{15}}{4}}{\\sqrt6}=\\dfrac{\\sqrt{10}}4</span>.</li><li>由余弦定理，<span class=\"gk-math\" data-tex=\"\\cos B=\\dfrac{a^2+c^2-b^2}{2ac}=\\dfrac{6+1-4}{2\\sqrt6}=\\dfrac{\\sqrt6}{4}\">\\cos B=\\dfrac{a^2+c^2-b^2}{2ac}=\\dfrac{6+1-4}{2\\sqrt6}=\\dfrac{\\sqrt6}{4}</span>. 又 <span class=\"gk-math\" data-tex=\"\\sin 2A=2\\sin A\\cos A=-\\dfrac{\\sqrt{15}}8\">\\sin 2A=2\\sin A\\cos A=-\\dfrac{\\sqrt{15}}8</span>，<span class=\"gk-math\" data-tex=\"\\cos 2A=2\\cos^2A-1=-\\dfrac78\">\\cos 2A=2\\cos^2A-1=-\\dfrac78</span>，故 <div class=\"gk-math display\" data-tex=\"\\sin(2A-B)=\\sin2A\\cos B-\\cos2A\\sin B\n=-\\dfrac{\\sqrt{15}}8\\cdot\\dfrac{\\sqrt6}{4}+\\dfrac78\\cdot\\dfrac{\\sqrt{10}}4\n=\\dfrac{\\sqrt{10}}8\">\\sin(2A-B)=\\sin2A\\cos B-\\cos2A\\sin B\n=-\\dfrac{\\sqrt{15}}8\\cdot\\dfrac{\\sqrt6}{4}+\\dfrac78\\cdot\\dfrac{\\sqrt{10}}4\n=\\dfrac{\\sqrt{10}}8</div></li></ol>","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-tianjin-q17","paperId":"2022-tianjin","number":17,"type":"written","score":15,"lessonIds":["8.5","e1-1.4"],"difficulty":"进阶","hint":"把A当原点，AB、AC、AA₁作三条坐标轴。中点坐标很容易写，线面角再找平面的法向量。","legacy":false,"legacyReason":"","searchText":"如图，在直三棱柱 ABC-A_1B_1C_1 中， AC\\perp AB ，点 D ， E ， F 分别为 A_1B_1 ， AA_1 ， CD 的中点， AB=AC=AA_1=2 . 求证： EF\\parallel 平面 ABC ； 求直线 BE 与平面 CC_1D 所成角的正弦值； 求平面 A_1CD 与平面 CC_1D 所成二面角的余弦值. ","questionHtml":"如图，在直三棱柱 <span class=\"gk-math\" data-tex=\"ABC-A_1B_1C_1\">ABC-A_1B_1C_1</span> 中，<span class=\"gk-math\" data-tex=\"AC\\perp AB\">AC\\perp AB</span>，点 <span class=\"gk-math\" data-tex=\"D\">D</span>，<span class=\"gk-math\" data-tex=\"E\">E</span>，<span class=\"gk-math\" data-tex=\"F\">F</span> 分别为 <span class=\"gk-math\" data-tex=\"A_1B_1\">A_1B_1</span>，<span class=\"gk-math\" data-tex=\"AA_1\">AA_1</span>，<span class=\"gk-math\" data-tex=\"CD\">CD</span> 的中点，<span class=\"gk-math\" data-tex=\"AB=AC=AA_1=2\">AB=AC=AA_1=2</span>.<br><br><ol class=\"gk-subparts\"><li>求证：<span class=\"gk-math\" data-tex=\"EF\\parallel\">EF\\parallel</span> 平面 <span class=\"gk-math\" data-tex=\"ABC\">ABC</span>；</li><li>求直线 <span class=\"gk-math\" data-tex=\"BE\">BE</span> 与平面 <span class=\"gk-math\" data-tex=\"CC_1D\">CC_1D</span> 所成角的正弦值；</li><li>求平面 <span class=\"gk-math\" data-tex=\"A_1CD\">A_1CD</span> 与平面 <span class=\"gk-math\" data-tex=\"CC_1D\">CC_1D</span> 所成二面角的余弦值.</li></ol><br><br><figure class=\"gk-figure\"><button class=\"gk-zoom\" style=\"width:min(100%,456px)\" data-action=\"zoom-image\" data-label=\"高考题图\" data-src=\"./assets/gaokao/figures/2022/tianjin/q17_fig1.webp\" aria-label=\"放大高考题图\"><img src=\"./assets/gaokao/figures/2022/tianjin/q17_fig1.webp\" alt=\"高考题图，点击可放大\" width=\"440\" height=\"339\" style=\"aspect-ratio:440/339;width:100%\" loading=\"lazy\"></button></figure>","optionsHtml":[],"answerHtml":"（1）证明见解析；（2）<span class=\"gk-math\" data-tex=\"\\frac45\">\\frac45</span>；（3）<span class=\"gk-math\" data-tex=\"\\frac{\\sqrt{10}}{10}\">\\frac{\\sqrt{10}}{10}</span>.","answerKey":"","solutionHtml":"<ol class=\"gk-subparts\"><li>建立空间直角坐标系，使 <span class=\"gk-math\" data-tex=\"A\">A</span> 为原点，<span class=\"gk-math\" data-tex=\"AB\">AB</span>，<span class=\"gk-math\" data-tex=\"AC\">AC</span>，<span class=\"gk-math\" data-tex=\"AA_1\">AA_1</span> 分别为 <span class=\"gk-math\" data-tex=\"x\">x</span> 轴，<span class=\"gk-math\" data-tex=\"y\">y</span> 轴，<span class=\"gk-math\" data-tex=\"z\">z</span> 轴，则 <span class=\"gk-math\" data-tex=\"A(0,0,0)\">A(0,0,0)</span>，<span class=\"gk-math\" data-tex=\"B(2,0,0)\">B(2,0,0)</span>，<span class=\"gk-math\" data-tex=\"C(0,2,0)\">C(0,2,0)</span>，<span class=\"gk-math\" data-tex=\"A_1(0,0,2)\">A_1(0,0,2)</span>，<span class=\"gk-math\" data-tex=\"B_1(2,0,2)\">B_1(2,0,2)</span>，<span class=\"gk-math\" data-tex=\"C_1(0,2,2)\">C_1(0,2,2)</span>. 由中点坐标公式得 <span class=\"gk-math\" data-tex=\"D(1,0,2)\">D(1,0,2)</span>，<span class=\"gk-math\" data-tex=\"E(0,0,1)\">E(0,0,1)</span>，<span class=\"gk-math\" data-tex=\"F(\\dfrac12,1,1)\">F(\\dfrac12,1,1)</span>，从而 <span class=\"gk-math\" data-tex=\"\\overrightarrow{EF}=(\\dfrac12,1,0)\">\\overrightarrow{EF}=(\\dfrac12,1,0)</span>. 该向量的 <span class=\"gk-math\" data-tex=\"z\">z</span> 坐标为 <span class=\"gk-math\" data-tex=\"0\">0</span>，且 <span class=\"gk-math\" data-tex=\"\\overrightarrow{EF}=\\dfrac14\\overrightarrow{AB}+\\dfrac12\\overrightarrow{AC}\">\\overrightarrow{EF}=\\dfrac14\\overrightarrow{AB}+\\dfrac12\\overrightarrow{AC}</span>，所以 <span class=\"gk-math\" data-tex=\"EF\\parallel\">EF\\parallel</span> 平面 <span class=\"gk-math\" data-tex=\"ABC\">ABC</span>.</li><li>由 <span class=\"gk-math\" data-tex=\"\\overrightarrow{CC_1}=(0,0,2)\">\\overrightarrow{CC_1}=(0,0,2)</span>，<span class=\"gk-math\" data-tex=\"\\overrightarrow{CD}=(1,-2,2)\">\\overrightarrow{CD}=(1,-2,2)</span>，可取平面 <span class=\"gk-math\" data-tex=\"CC_1D\">CC_1D</span> 的一个法向量为 <span class=\"gk-math\" data-tex=\"\\bs n=(2,1,0)\">\\bs n=(2,1,0)</span>. 又 <span class=\"gk-math\" data-tex=\"\\overrightarrow{BE}=(-2,0,1)\">\\overrightarrow{BE}=(-2,0,1)</span>，所以直线 <span class=\"gk-math\" data-tex=\"BE\">BE</span> 与平面 <span class=\"gk-math\" data-tex=\"CC_1D\">CC_1D</span> 所成角的正弦值为 <div class=\"gk-math display\" data-tex=\"\\dfrac{|\\overrightarrow{BE}\\cdot\\bs n|}{|\\overrightarrow{BE}|\\cdot|\\bs n|}=\\dfrac{4}{\\sqrt{5}\\sqrt{5}}=\\dfrac45\">\\dfrac{|\\overrightarrow{BE}\\cdot\\bs n|}{|\\overrightarrow{BE}|\\cdot|\\bs n|}=\\dfrac{4}{\\sqrt{5}\\sqrt{5}}=\\dfrac45</div></li><li>平面 <span class=\"gk-math\" data-tex=\"A_1CD\">A_1CD</span> 的一个法向量可取 <span class=\"gk-math\" data-tex=\"\\bs m=(0,1,1)\">\\bs m=(0,1,1)</span>，平面 <span class=\"gk-math\" data-tex=\"CC_1D\">CC_1D</span> 的一个法向量为 <span class=\"gk-math\" data-tex=\"\\bs n=(2,1,0)\">\\bs n=(2,1,0)</span>. 因此两平面所成二面角的余弦值为 <div class=\"gk-math display\" data-tex=\"\\dfrac{|\\bs m\\cdot\\bs n|}{|\\bs m|\\cdot|\\bs n|}=\\dfrac{1}{\\sqrt{2}\\sqrt{5}}=\\dfrac{\\sqrt{10}}{10}\">\\dfrac{|\\bs m\\cdot\\bs n|}{|\\bs m|\\cdot|\\bs n|}=\\dfrac{1}{\\sqrt{2}\\sqrt{5}}=\\dfrac{\\sqrt{10}}{10}</div></li></ol>","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-tianjin-q18","paperId":"2022-tianjin","number":18,"type":"written","score":15,"lessonIds":["e2-4.2","e2-4.3"],"difficulty":"挑战","hint":"用公差d、公比q写出前三项，先解d和q。最后一问把相邻的奇数项、偶数项配成一组。","legacy":false,"legacyReason":"","searchText":"设 \\{a_n\\} 为等差数列， \\{b_n\\} 为等比数列，且 a_1=b_1=a_2-b_2=a_3-b_3=1 . 求 \\{a_n\\} 和 \\{b_n\\} 的通项公式； 记 \\{a_n\\} 的前 n 项和为 S_n ，求证： \\left(S_{n+1}+a_{n+1}\\right)b_n=S_{n+1}b_{n+1}-S_nb_n ； 求 \\displaystyle\\sum_{k=1}^{2n}\\left[a_{k+1}-(-1)^ka_k\\right]b_k . ","questionHtml":"设 <span class=\"gk-math\" data-tex=\"\\{a_n\\}\">\\{a_n\\}</span> 为等差数列，<span class=\"gk-math\" data-tex=\"\\{b_n\\}\">\\{b_n\\}</span> 为等比数列，且 <span class=\"gk-math\" data-tex=\"a_1=b_1=a_2-b_2=a_3-b_3=1\">a_1=b_1=a_2-b_2=a_3-b_3=1</span>.<br><br><ol class=\"gk-subparts\"><li>求 <span class=\"gk-math\" data-tex=\"\\{a_n\\}\">\\{a_n\\}</span> 和 <span class=\"gk-math\" data-tex=\"\\{b_n\\}\">\\{b_n\\}</span> 的通项公式；</li><li>记 <span class=\"gk-math\" data-tex=\"\\{a_n\\}\">\\{a_n\\}</span> 的前 <span class=\"gk-math\" data-tex=\"n\">n</span> 项和为 <span class=\"gk-math\" data-tex=\"S_n\">S_n</span>，求证：<span class=\"gk-math\" data-tex=\"\\left(S_{n+1}+a_{n+1}\\right)b_n=S_{n+1}b_{n+1}-S_nb_n\">\\left(S_{n+1}+a_{n+1}\\right)b_n=S_{n+1}b_{n+1}-S_nb_n</span>；</li><li>求 <span class=\"gk-math\" data-tex=\"\\displaystyle\\sum_{k=1}^{2n}\\left[a_{k+1}-(-1)^ka_k\\right]b_k\">\\displaystyle\\sum_{k=1}^{2n}\\left[a_{k+1}-(-1)^ka_k\\right]b_k</span>.</li></ol>","optionsHtml":[],"answerHtml":"（1）<span class=\"gk-math\" data-tex=\"a_n=2n-1\">a_n=2n-1</span>，<span class=\"gk-math\" data-tex=\"b_n=2^{n-1}\">b_n=2^{n-1}</span>；（2）证明见解析；（3）<span class=\"gk-math\" data-tex=\"\\frac{8((3n-1)4^n+1)}9\">\\frac{8((3n-1)4^n+1)}9</span>.","answerKey":"","solutionHtml":"<ol class=\"gk-subparts\"><li>设等差数列 <span class=\"gk-math\" data-tex=\"\\{a_n\\}\">\\{a_n\\}</span> 的公差为 <span class=\"gk-math\" data-tex=\"d\">d</span>，等比数列 <span class=\"gk-math\" data-tex=\"\\{b_n\\}\">\\{b_n\\}</span> 的公比为 <span class=\"gk-math\" data-tex=\"q\">q</span>. 由题意，<span class=\"gk-math\" data-tex=\"a_2=1+d\">a_2=1+d</span>，<span class=\"gk-math\" data-tex=\"a_3=1+2d\">a_3=1+2d</span>，<span class=\"gk-math\" data-tex=\"b_2=q\">b_2=q</span>，<span class=\"gk-math\" data-tex=\"b_3=q^2\">b_3=q^2</span>，所以 <span class=\"gk-math\" data-tex=\"d=q\">d=q</span>，且 <span class=\"gk-math\" data-tex=\"2q-q^2=0\">2q-q^2=0</span>. 等比数列的公比不为 <span class=\"gk-math\" data-tex=\"0\">0</span>，故 <span class=\"gk-math\" data-tex=\"q=2\">q=2</span>，从而 <span class=\"gk-math\" data-tex=\"d=2\">d=2</span>. 因此 <span class=\"gk-math\" data-tex=\"a_n=1+2(n-1)=2n-1\">a_n=1+2(n-1)=2n-1</span>，<span class=\"gk-math\" data-tex=\"b_n=2^{n-1}\">b_n=2^{n-1}</span>.</li><li>由 <span class=\"gk-math\" data-tex=\"a_k=2k-1\">a_k=2k-1</span> 得 <span class=\"gk-math\" data-tex=\"S_n=\\sum_{k=1}^n(2k-1)=n^2\">S_n=\\sum_{k=1}^n(2k-1)=n^2</span>. 于是 <div class=\"gk-math display\" data-tex=\"(S_{n+1}+a_{n+1})b_n=((n+1)^2+2n+1)2^{n-1}=(n^2+4n+2)2^{n-1}\">(S_{n+1}+a_{n+1})b_n=((n+1)^2+2n+1)2^{n-1}=(n^2+4n+2)2^{n-1}</div> 而 <div class=\"gk-math display\" data-tex=\"S_{n+1}b_{n+1}-S_nb_n=((n+1)^2\\cdot2^n-n^2\\cdot2^{n-1})=(n^2+4n+2)2^{n-1}\">S_{n+1}b_{n+1}-S_nb_n=((n+1)^2\\cdot2^n-n^2\\cdot2^{n-1})=(n^2+4n+2)2^{n-1}</div> 所以 <span class=\"gk-math\" data-tex=\"(S_{n+1}+a_{n+1})b_n=S_{n+1}b_{n+1}-S_nb_n\">(S_{n+1}+a_{n+1})b_n=S_{n+1}b_{n+1}-S_nb_n</span>.</li><li>由通项公式，原式为 <div class=\"gk-math display\" data-tex=\"\\sum_{k=1}^{2n}\\left[2k+1-(-1)^k(2k-1)\\right]2^{k-1}\">\\sum_{k=1}^{2n}\\left[2k+1-(-1)^k(2k-1)\\right]2^{k-1}</div> 当 <span class=\"gk-math\" data-tex=\"k=2j-1\">k=2j-1</span> 时，对应项为 <span class=\"gk-math\" data-tex=\"(8j-4)4^{j-1}\">(8j-4)4^{j-1}</span>；当 <span class=\"gk-math\" data-tex=\"k=2j\">k=2j</span> 时，对应项为 <span class=\"gk-math\" data-tex=\"4\\cdot4^{j-1}\">4\\cdot4^{j-1}</span>. 因此原式等于 <div class=\"gk-math display\" data-tex=\"\\sum_{j=1}^n8j4^{j-1}=8\\sum_{j=1}^n j4^{j-1}\">\\sum_{j=1}^n8j4^{j-1}=8\\sum_{j=1}^n j4^{j-1}</div> 设 <span class=\"gk-math\" data-tex=\"T=\\sum_{j=1}^n j4^{j-1}\">T=\\sum_{j=1}^n j4^{j-1}</span>，则 <div class=\"gk-math display\" data-tex=\"3T=4T-T=n4^n-\\sum_{j=1}^n4^{j-1}=n4^n-\\dfrac{4^n-1}{3}\">3T=4T-T=n4^n-\\sum_{j=1}^n4^{j-1}=n4^n-\\dfrac{4^n-1}{3}</div> 故 <span class=\"gk-math\" data-tex=\"T=\\dfrac{(3n-1)4^n+1}{9}\">T=\\dfrac{(3n-1)4^n+1}{9}</span>，原式为 <span class=\"gk-math\" data-tex=\"\\dfrac{8\\left((3n-1)4^n+1\\right)}{9}\">\\dfrac{8\\left((3n-1)4^n+1\\right)}{9}</span>.</li></ol>","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-tianjin-q19","paperId":"2022-tianjin","number":19,"type":"written","score":15,"lessonIds":["e1-3.1","e1-2.2"],"difficulty":"挑战","hint":"BF的长度就是a，先由两条线段的比例求a、b的关系。第二问利用切线与椭圆只有一个公共点。","legacy":false,"legacyReason":"","searchText":"椭圆 \\dfrac{x^2}{a^2}+\\dfrac{y^2}{b^2}=1 （ a>b>0 ）的右焦点为 F ，右顶点为 A ，上顶点为 B ，且满足 \\dfrac{|BF|}{|AB|}=\\dfrac{\\sqrt{3}}{2} . 求椭圆的离心率 e ； 直线 l 与椭圆有唯一公共点 M ，与 y 轴相交于 N （ N 异于 M ）. 记 O 为坐标原点，若 |OM|=|ON| ，且 \\triangle OMN 的面积为 \\sqrt{3} ，求椭圆的标准方程. ","questionHtml":"椭圆 <span class=\"gk-math\" data-tex=\"\\dfrac{x^2}{a^2}+\\dfrac{y^2}{b^2}=1\">\\dfrac{x^2}{a^2}+\\dfrac{y^2}{b^2}=1</span>（<span class=\"gk-math\" data-tex=\"a&gt;b&gt;0\">a&gt;b&gt;0</span>）的右焦点为 <span class=\"gk-math\" data-tex=\"F\">F</span>，右顶点为 <span class=\"gk-math\" data-tex=\"A\">A</span>，上顶点为 <span class=\"gk-math\" data-tex=\"B\">B</span>，且满足 <span class=\"gk-math\" data-tex=\"\\dfrac{|BF|}{|AB|}=\\dfrac{\\sqrt{3}}{2}\">\\dfrac{|BF|}{|AB|}=\\dfrac{\\sqrt{3}}{2}</span>.<br><br><ol class=\"gk-subparts\"><li>求椭圆的离心率 <span class=\"gk-math\" data-tex=\"e\">e</span>；</li><li>直线 <span class=\"gk-math\" data-tex=\"l\">l</span> 与椭圆有唯一公共点 <span class=\"gk-math\" data-tex=\"M\">M</span>，与 <span class=\"gk-math\" data-tex=\"y\">y</span> 轴相交于 <span class=\"gk-math\" data-tex=\"N\">N</span>（<span class=\"gk-math\" data-tex=\"N\">N</span> 异于 <span class=\"gk-math\" data-tex=\"M\">M</span>）. 记 <span class=\"gk-math\" data-tex=\"O\">O</span> 为坐标原点，若 <span class=\"gk-math\" data-tex=\"|OM|=|ON|\">|OM|=|ON|</span>，且 <span class=\"gk-math\" data-tex=\"\\triangle OMN\">\\triangle OMN</span> 的面积为 <span class=\"gk-math\" data-tex=\"\\sqrt{3}\">\\sqrt{3}</span>，求椭圆的标准方程.</li></ol>","optionsHtml":[],"answerHtml":"（1）<span class=\"gk-math\" data-tex=\"e=\\frac{\\sqrt6}3\">e=\\frac{\\sqrt6}3</span>；（2）<span class=\"gk-math\" data-tex=\"\\frac{x^2}6+\\frac{y^2}2=1\">\\frac{x^2}6+\\frac{y^2}2=1</span>.","answerKey":"","solutionHtml":"<ol class=\"gk-subparts\"><li>设椭圆的半焦距为 <span class=\"gk-math\" data-tex=\"c\">c</span>，则 <span class=\"gk-math\" data-tex=\"c^2=a^2-b^2\">c^2=a^2-b^2</span>，且 <span class=\"gk-math\" data-tex=\"F=(c,0)\">F=(c,0)</span>. 因为 <span class=\"gk-math\" data-tex=\"B=(0,b)\">B=(0,b)</span>，所以 <span class=\"gk-math\" data-tex=\"|BF|=\\sqrt{b^2+c^2}=a\">|BF|=\\sqrt{b^2+c^2}=a</span>，又 <span class=\"gk-math\" data-tex=\"|AB|=\\sqrt{a^2+b^2}\">|AB|=\\sqrt{a^2+b^2}</span>. 由题设 <div class=\"gk-math display\" data-tex=\"\\dfrac{a}{\\sqrt{a^2+b^2}}=\\dfrac{\\sqrt{3}}{2}\">\\dfrac{a}{\\sqrt{a^2+b^2}}=\\dfrac{\\sqrt{3}}{2}</div> 得 <span class=\"gk-math\" data-tex=\"4a^2=3a^2+3b^2\">4a^2=3a^2+3b^2</span>，即 <span class=\"gk-math\" data-tex=\"a^2=3b^2\">a^2=3b^2</span>. 因此 <span class=\"gk-math\" data-tex=\"e=\\dfrac{c}{a}=\\sqrt{1-\\dfrac{b^2}{a^2}}=\\sqrt{\\dfrac23}=\\dfrac{\\sqrt6}{3}\">e=\\dfrac{c}{a}=\\sqrt{1-\\dfrac{b^2}{a^2}}=\\sqrt{\\dfrac23}=\\dfrac{\\sqrt6}{3}</span>.</li><li>设唯一公共点为 <span class=\"gk-math\" data-tex=\"M=(x_0,y_0)\">M=(x_0,y_0)</span>. 由 <span class=\"gk-math\" data-tex=\"a^2=3b^2\">a^2=3b^2</span>，椭圆方程给出 <span class=\"gk-math\" data-tex=\"x_0^2=3b^2-3y_0^2\">x_0^2=3b^2-3y_0^2</span>. 直线 <span class=\"gk-math\" data-tex=\"l\">l</span> 为椭圆在 <span class=\"gk-math\" data-tex=\"M\">M</span> 处的切线，其方程为 <span class=\"gk-math\" data-tex=\"\\dfrac{x x_0}{a^2}+\\dfrac{y y_0}{b^2}=1\">\\dfrac{x x_0}{a^2}+\\dfrac{y y_0}{b^2}=1</span>，故它与 <span class=\"gk-math\" data-tex=\"y\">y</span> 轴的交点为 <span class=\"gk-math\" data-tex=\"N=(0,\\dfrac{b^2}{y_0})\">N=(0,\\dfrac{b^2}{y_0})</span>. 条件 <span class=\"gk-math\" data-tex=\"|OM|=|ON|\">|OM|=|ON|</span> 给出 <div class=\"gk-math display\" data-tex=\"x_0^2+y_0^2=\\dfrac{b^4}{y_0^2}\">x_0^2+y_0^2=\\dfrac{b^4}{y_0^2}</div> 令 <span class=\"gk-math\" data-tex=\"t=\\dfrac{y_0^2}{b^2}\">t=\\dfrac{y_0^2}{b^2}</span>，则 <span class=\"gk-math\" data-tex=\"0&lt;t&lt;1\">0&lt;t&lt;1</span>，代入 <span class=\"gk-math\" data-tex=\"x_0^2=3b^2(1-t)\">x_0^2=3b^2(1-t)</span> 得 <span class=\"gk-math\" data-tex=\"3-2t=\\dfrac1t\">3-2t=\\dfrac1t</span>，即 <span class=\"gk-math\" data-tex=\"2t^2-3t+1=0\">2t^2-3t+1=0</span>. 所以 <span class=\"gk-math\" data-tex=\"t=1\">t=1</span> 或 <span class=\"gk-math\" data-tex=\"t=\\dfrac12\">t=\\dfrac12</span>. <span class=\"gk-math\" data-tex=\"t=1\">t=1</span> 时 <span class=\"gk-math\" data-tex=\"x_0=0\">x_0=0</span>，三角形面积为 <span class=\"gk-math\" data-tex=\"0\">0</span>，与题设矛盾，故 <span class=\"gk-math\" data-tex=\"t=\\dfrac12\">t=\\dfrac12</span>.<br><br>又因为 <span class=\"gk-math\" data-tex=\"\\triangle OMN\">\\triangle OMN</span> 的面积为 <span class=\"gk-math\" data-tex=\"\\sqrt3\">\\sqrt3</span>，所以 <div class=\"gk-math display\" data-tex=\"\\sqrt3=\\dfrac12|x_0|\\left|\\dfrac{b^2}{y_0}\\right|=\\dfrac{\\sqrt3}{2}b^2\">\\sqrt3=\\dfrac12|x_0|\\left|\\dfrac{b^2}{y_0}\\right|=\\dfrac{\\sqrt3}{2}b^2</div> 从而 <span class=\"gk-math\" data-tex=\"b^2=2\">b^2=2</span>，<span class=\"gk-math\" data-tex=\"a^2=6\">a^2=6</span>. 故椭圆的标准方程为 <span class=\"gk-math\" data-tex=\"\\dfrac{x^2}{6}+\\dfrac{y^2}{2}=1\">\\dfrac{x^2}{6}+\\dfrac{y^2}{2}=1</span>.</li></ol>","sourceNote":"","specialNote":"","answerAlternatives":[]},{"id":"2022-tianjin-q20","paperId":"2022-tianjin","number":20,"type":"written","score":16,"lessonIds":["e2-5.1","e2-5.3","2.2"],"difficulty":"挑战","hint":"切线先算f(0)和f′(0)。公共点条件可以改写为eˣ=a sin x+b√x，再想怎样比较a²+b²。","legacy":false,"legacyReason":"","searchText":"已知 a ， b\\in\\R ，函数 f(x)=\\e^x-a\\sin x ， g(x)=b\\sqrt{x} . 求函数 y=f(x) 在点 (0,f(0)) 处的切线方程； 若 y=f(x) 和 y=g(x) 有公共点， 当 a=0 时，求 b 的取值范围； 求证： a^2+b^2>\\e . ","questionHtml":"已知 <span class=\"gk-math\" data-tex=\"a\">a</span>，<span class=\"gk-math\" data-tex=\"b\\in\\R\">b\\in\\R</span>，函数 <span class=\"gk-math\" data-tex=\"f(x)=\\e^x-a\\sin x\">f(x)=\\e^x-a\\sin x</span>，<span class=\"gk-math\" data-tex=\"g(x)=b\\sqrt{x}\">g(x)=b\\sqrt{x}</span>.<br><br><ol class=\"gk-subparts\"><li>求函数 <span class=\"gk-math\" data-tex=\"y=f(x)\">y=f(x)</span> 在点 <span class=\"gk-math\" data-tex=\"(0,f(0))\">(0,f(0))</span> 处的切线方程；</li><li>若 <span class=\"gk-math\" data-tex=\"y=f(x)\">y=f(x)</span> 和 <span class=\"gk-math\" data-tex=\"y=g(x)\">y=g(x)</span> 有公共点， <ol class=\"gk-subparts\"><li>当 <span class=\"gk-math\" data-tex=\"a=0\">a=0</span> 时，求 <span class=\"gk-math\" data-tex=\"b\">b</span> 的取值范围；</li><li>求证：<span class=\"gk-math\" data-tex=\"a^2+b^2&gt;\\e\">a^2+b^2&gt;\\e</span>.</li></ol></li></ol>","optionsHtml":[],"answerHtml":"（1）<span class=\"gk-math\" data-tex=\"y=(1-a)x+1\">y=(1-a)x+1</span>；（2）①<span class=\"gk-math\" data-tex=\"b\\in[\\sqrt{2\\e},+\\infty)\">b\\in[\\sqrt{2\\e},+\\infty)</span>；②证明见解析.","answerKey":"","solutionHtml":"<ol class=\"gk-subparts\"><li><span class=\"gk-math\" data-tex=\"f(0)=1\">f(0)=1</span>，<span class=\"gk-math\" data-tex=\"f&#x27;(x)=\\e^x-a\\cos x\">f&#x27;(x)=\\e^x-a\\cos x</span>，所以 <span class=\"gk-math\" data-tex=\"f&#x27;(0)=1-a\">f&#x27;(0)=1-a</span>. 因此曲线在 <span class=\"gk-math\" data-tex=\"(0,f(0))=(0,1)\">(0,f(0))=(0,1)</span> 处的切线方程为 <span class=\"gk-math\" data-tex=\"y-1=(1-a)x\">y-1=(1-a)x</span>，即 <span class=\"gk-math\" data-tex=\"y=(1-a)x+1\">y=(1-a)x+1</span>.</li><li><ol class=\"gk-subparts\"><li>当 <span class=\"gk-math\" data-tex=\"a=0\">a=0</span> 时，公共点的横坐标满足 <span class=\"gk-math\" data-tex=\"x&gt;0\">x&gt;0</span>，并且 <span class=\"gk-math\" data-tex=\"\\e^x=b\\sqrt{x}\">\\e^x=b\\sqrt{x}</span>，即 <span class=\"gk-math\" data-tex=\"b=\\dfrac{\\e^x}{\\sqrt{x}}\">b=\\dfrac{\\e^x}{\\sqrt{x}}</span>. 若 <span class=\"gk-math\" data-tex=\"b\\le0\">b\\le0</span>，等式不可能成立. 令 <span class=\"gk-math\" data-tex=\"h(x)=\\dfrac{\\e^x}{\\sqrt{x}}\">h(x)=\\dfrac{\\e^x}{\\sqrt{x}}</span>，则 <div class=\"gk-math display\" data-tex=\"h&#x27;(x)=\\dfrac{\\e^x}{x^{\\frac{3}{2}}}\\left(x-\\dfrac12\\right)\">h&#x27;(x)=\\dfrac{\\e^x}{x^{\\frac{3}{2}}}\\left(x-\\dfrac12\\right)</div> 所以 <span class=\"gk-math\" data-tex=\"h(x)\">h(x)</span> 在 <span class=\"gk-math\" data-tex=\"(0,\\dfrac12)\">(0,\\dfrac12)</span> 上递减，在 <span class=\"gk-math\" data-tex=\"(\\dfrac12,+\\infty)\">(\\dfrac12,+\\infty)</span> 上递增，最小值为 <span class=\"gk-math\" data-tex=\"h(\\dfrac12)=\\sqrt{2\\e}\">h(\\dfrac12)=\\sqrt{2\\e}</span>. 故 <span class=\"gk-math\" data-tex=\"b\\in[\\sqrt{2\\e},+\\infty)\">b\\in[\\sqrt{2\\e},+\\infty)</span>.</li><li>公共点的横坐标不能为 <span class=\"gk-math\" data-tex=\"0\">0</span>，设其为 <span class=\"gk-math\" data-tex=\"x&gt;0\">x&gt;0</span>. 由公共点条件，<span class=\"gk-math\" data-tex=\"\\e^x=a\\sin x+b\\sqrt{x}\">\\e^x=a\\sin x+b\\sqrt{x}</span>. 由柯西不等式， <div class=\"gk-math display\" data-tex=\"\\e^{2x}\\le(a^2+b^2)(\\sin^2x+x)\">\\e^{2x}\\le(a^2+b^2)(\\sin^2x+x)</div> 对任意 <span class=\"gk-math\" data-tex=\"x&gt;0\">x&gt;0</span>，都有 <span class=\"gk-math\" data-tex=\"\\sin^2x&lt;x\">\\sin^2x&lt;x</span>：当 <span class=\"gk-math\" data-tex=\"0&lt;x&lt;1\">0&lt;x&lt;1</span> 时，<span class=\"gk-math\" data-tex=\"\\sin^2x&lt;x^2&lt;x\">\\sin^2x&lt;x^2&lt;x</span>；当 <span class=\"gk-math\" data-tex=\"x\\ge1\">x\\ge1</span> 时，<span class=\"gk-math\" data-tex=\"\\sin^2x\\le1\\le x\">\\sin^2x\\le1\\le x</span>，且 <span class=\"gk-math\" data-tex=\"x=1\">x=1</span> 时仍为严格不等式. 因此 <span class=\"gk-math\" data-tex=\"x+\\sin^2x&lt;2x\">x+\\sin^2x&lt;2x</span>. 又由 <span class=\"gk-math\" data-tex=\"\\e^u\\ge1+u\">\\e^u\\ge1+u</span>（取 <span class=\"gk-math\" data-tex=\"u=2x-1\">u=2x-1</span>），得 <span class=\"gk-math\" data-tex=\"\\e^{2x-1}\\ge2x\">\\e^{2x-1}\\ge2x</span>，从而 <span class=\"gk-math\" data-tex=\"\\e^{2x-1}&gt;x+\\sin^2x\">\\e^{2x-1}&gt;x+\\sin^2x</span>. 于是 <div class=\"gk-math display\" data-tex=\"a^2+b^2\\ge\\dfrac{\\e^{2x}}{x+\\sin^2x}&gt;\\e\">a^2+b^2\\ge\\dfrac{\\e^{2x}}{x+\\sin^2x}&gt;\\e</div> 即 <span class=\"gk-math\" data-tex=\"a^2+b^2&gt;\\e\">a^2+b^2&gt;\\e</span>.</li></ol></li></ol>","sourceNote":"","specialNote":"","answerAlternatives":[]}];
